from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
import numpy as np

env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

state = env.reset()

print("✅ Environment loaded")
print("State shape:", state.shape)
print("Number of nodes:", env.num_nodes)
print("Features per node:", len(state) // env.num_nodes)

print("\nCapacity factors:")
print(env.capacity_factor)

print("\nBase latency:")
print(env.base_latency)

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
import numpy as np

# Separate environment for testing only
# so we do not disturb the future training experiment
test_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

state = test_env.reset()

# Fixed action generator so this test is reproducible
action_rng = np.random.default_rng(123)

print("🧪 Testing 10 scheduling steps")
print("=" * 95)

total_reward = 0.0
deadline_misses = 0

for step in range(10):

    action = int(
        action_rng.integers(0, test_env.num_nodes)
    )

    next_state, reward, done, info = test_env.step(action)

    total_reward += reward
    deadline_misses += int(info["deadline_miss"])

    status = (
        "❌ MISS"
        if info["deadline_miss"] == 1
        else "✅ MET"
    )

    print(
        f"Step {step+1:2d} | "
        f"Node {action:2d} | "
        f"Exec={info['exec_time']:6.1f} ms | "
        f"Wait={info['waiting_time']:6.1f} ms | "
        f"Lat={info['latency']:5.1f} ms | "
        f"RT={info['response_time']:6.1f} ms | "
        f"Deadline={info['deadline']:6.1f} ms | "
        f"Reward={reward:7.2f} | "
        f"{status}"
    )

    state = next_state

print("=" * 95)

print(f"\nTotal reward: {total_reward:.2f}")
print(f"Deadline misses: {deadline_misses}/10")
print(f"Deadline met: {10-deadline_misses}/10")
print(f"Final average queue: {np.mean(test_env.queue_ms):.2f} ms")
print(f"Final average energy: {np.mean(test_env.energy):.6f}")

