from ReplayBuffer import ReplayBuffer

buffer = ReplayBuffer(
    capacity=100_000
)

# Add dummy experiences
dummy_state = np.zeros(75, dtype=np.float32)
dummy_next_state = np.ones(75, dtype=np.float32)

for i in range(100):
    buffer.add(
        dummy_state,
        i % 15,
        float(i),
        dummy_next_state
    )

print("✅ ReplayBuffer loaded")
print("Stored transitions:", len(buffer))

states, actions, rewards, next_states = buffer.sample(64)

print("\nBatch shapes:")
print("States:", states.shape)
print("Actions:", actions.shape)
print("Rewards:", rewards.shape)
print("Next states:", next_states.shape)

print("\nDevice:", states.device)

