import torch
from ImprovedDQN import ImprovedDQN

num_nodes = 15
state_dim = 75
action_dim = 15

model = ImprovedDQN(
    state_dim=state_dim,
    action_dim=action_dim,
    num_nodes=num_nodes,
    hidden_dim=128
).cuda()

# مهم بسبب BatchNorm
model.eval()

dummy_state = torch.zeros(
    1,
    75,
    device="cuda"
)

with torch.no_grad():
    q_values = model(
        dummy_state
    )

print("✅ ADDQN network loaded")

print(
    "Input shape:",
    dummy_state.shape
)

print(
    "Q-values shape:",
    q_values.shape
)

print(
    "Number of parameters:",
    sum(
        p.numel()
        for p in model.parameters()
    )
)

print(
    "Device:",
    next(model.parameters()).device
)

