print(
    "Device:",
    agent.device
)

print(
    "Policy parameters:",
    sum(
        p.numel()
        for p in agent.policy_net.parameters()
    )
)

print(
    "Target parameters:",
    sum(
        p.numel()
        for p in agent.target_net.parameters()
    )
)

# Test action selection
test_state = np.zeros(
    state_dim,
    dtype=np.float32
)

action = agent.select_action(
    test_state,
    epsilon=0.0
)

print(
    "Greedy test action:",
    action
)

print(
    "Initial learning rate:",
    agent.get_current_lr()
)

