import numpy as np

# Fresh environment
train_test_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

# Fresh agent
train_test_agent = ImprovedDQNAgent(
    state_dim=75,
    action_dim=15,
    num_nodes=15,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=128,
    use_lr_scheduler=True
)

state = train_test_env.reset()

# Collect 100 real transitions
for step in range(100):

    action = train_test_agent.select_action(
        state,
        epsilon=1.0   # fully exploratory for this test
    )

    next_state, reward, done, info = train_test_env.step(action)

    train_test_agent.memory.add(
        state,
        action,
        reward,
        next_state
    )

    state = next_state

    if done:
        state = train_test_env.reset()

print("✅ Real transitions collected")
print("Replay buffer size:", len(train_test_agent.memory))

# One training update
loss = train_test_agent.train(
    batch_size=64
)

print("\n✅ One Double-DQN training update completed")
print("Loss:", loss)
print("Training steps:", train_test_agent.training_steps)
print("Current learning rate:", train_test_agent.get_current_lr())

import random
import numpy as np
import torch

def set_global_seed(seed=42):
    random.seed(seed)
    np.random.seed(seed)

    torch.manual_seed(seed)

    if torch.cuda.is_available():
        torch.cuda.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)

    print(f"✅ Global seed fixed at {seed}")

set_global_seed(42)

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from ImprovedDQNAgent import ImprovedDQNAgent

# =====================================================
# Small 5-episode smoke test
# =====================================================

set_global_seed(42)

env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

state_dim = len(env.reset())
action_dim = env.num_nodes

agent = ImprovedDQNAgent(
    state_dim=state_dim,
    action_dim=action_dim,
    num_nodes=env.num_nodes,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=128,
    use_lr_scheduler=True
)

episodes = 5

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

batch_size = 64
target_update_freq = 5

print("🧪 Starting 5-episode smoke test")
print("=" * 85)

for episode in range(episodes):

    state = env.reset()

    total_reward = 0.0

    response_times = []
    deadline_misses = []
    overloads = []

    episode_losses = []

    for step in range(env.max_steps):

        action = agent.select_action(
            state,
            epsilon
        )

        next_state, reward, done, info = env.step(action)

        agent.memory.add(
            state,
            action,
            reward,
            next_state
        )

        loss = agent.train(
            batch_size=batch_size
        )

        if loss is not None:
            episode_losses.append(loss)

        state = next_state
        total_reward += reward

        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        if done:
            break

    # epsilon decay
    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )

    # target-network update
    if episode % target_update_freq == 0:
        agent.update_target()

    # learning-rate scheduler
    agent.step_scheduler()

    avg_rt = np.mean(response_times)

    dmr = np.mean(deadline_misses)

    met_ratio = 1.0 - dmr

    overload_ratio = np.mean(overloads)

    avg_loss = (
        np.mean(episode_losses)
        if len(episode_losses) > 0
        else 0.0
    )

    print(
        f"Episode {episode+1:2d} | "
        f"Reward={total_reward:8.2f} | "
        f"RT={avg_rt:7.2f} ms | "
        f"DMR={dmr:.3f} | "
        f"Met={met_ratio:.3f} | "
        f"Overload={overload_ratio:.3f} | "
        f"Loss={avg_loss:8.3f} | "
        f"Epsilon={epsilon:.3f}"
    )

print("=" * 85)
print("✅ Smoke test completed")
print("Replay buffer:", len(agent.memory))
print("Training updates:", agent.training_steps)

