import os
import time
import random
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from ImprovedDQNAgent import ImprovedDQNAgent


# =====================================================
# 1. Reproducibility
# =====================================================
set_global_seed(42)


# =====================================================
# 2. Output files
# =====================================================
CSV_PATH = os.path.join(
    SAVE_DIR,
    "original_ADDQN_training_500episodes.csv"
)

CHECKPOINT_PATH = os.path.join(
    SAVE_DIR,
    "original_ADDQN_rolling_checkpoint.pt"
)

FINAL_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "original_ADDQN_final_model.pth"
)


# =====================================================
# 3. Fresh Environment
# =====================================================
env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

state_dim = len(env.reset())
action_dim = env.num_nodes


# =====================================================
# 4. Fresh ADDQN Agent
# =====================================================
agent = ImprovedDQNAgent(
    state_dim=state_dim,
    action_dim=action_dim,
    num_nodes=env.num_nodes,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=128,
    use_lr_scheduler=True
)


# =====================================================
# 5. Original Training Hyperparameters
# =====================================================
episodes = 500

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

batch_size = 64
target_update_freq = 5


# =====================================================
# 6. Training log
# =====================================================
training_rows = []

print("🚀 Starting ORIGINAL ADDQN training")
print("Episodes:", episodes)
print("Steps per episode:", env.max_steps)
print("Total expected interactions:", episodes * env.max_steps)
print("Device:", agent.device)
print("=" * 100)

training_start = time.time()


# =====================================================
# 7. Training Loop
# =====================================================
for episode in range(episodes):

    episode_start = time.time()

    state = env.reset()

    total_reward = 0.0

    response_times = []
    deadline_misses = []
    overloads = []

    avg_cpus = []
    avg_queues = []
    avg_energies = []
    chosen_latencies = []

    episode_losses = []


    for step in range(env.max_steps):

        # -----------------------------
        # Choose action
        # -----------------------------
        action = agent.select_action(
            state,
            epsilon
        )

        # -----------------------------
        # Environment step
        # -----------------------------
        next_state, reward, done, info = env.step(action)

        # -----------------------------
        # Store transition
        # -----------------------------
        agent.memory.add(
            state,
            action,
            reward,
            next_state
        )

        # -----------------------------
        # Train ADDQN
        # -----------------------------
        loss = agent.train(
            batch_size=batch_size
        )

        if loss is not None:
            episode_losses.append(loss)

        # -----------------------------
        # Update state
        # -----------------------------
        state = next_state

        total_reward += reward

        # -----------------------------
        # Record metrics
        # -----------------------------
        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        avg_cpus.append(
            info["avg_cpu"]
        )

        avg_queues.append(
            info["avg_queue_ms"]
        )

        avg_energies.append(
            info["avg_energy"]
        )

        chosen_latencies.append(
            info["latency"]
        )

        if done:
            break


    # =================================================
    # End of episode
    # =================================================

    # Decay epsilon
    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )

    # Original target update schedule
    if episode % target_update_freq == 0:
        agent.update_target()

    # Original LR scheduler
    agent.step_scheduler()


    # =================================================
    # Metrics
    # =================================================

    avg_rt = float(
        np.mean(response_times)
    )

    dmr = float(
        np.mean(deadline_misses)
    )

    deadline_met_ratio = float(
        1.0 - dmr
    )

    overload_ratio = float(
        np.mean(overloads)
    )

    episode_avg_loss = (
        float(np.mean(episode_losses))
        if len(episode_losses) > 0
        else 0.0
    )

    stats = agent.get_training_stats()

    episode_time = (
        time.time() - episode_start
    )


    training_rows.append({

        "episode": episode + 1,

        "total_reward": float(total_reward),

        "avg_rt": avg_rt,

        "dmr": dmr,

        "deadline_met_ratio":
            deadline_met_ratio,

        "overload_ratio":
            overload_ratio,

        "epsilon":
            float(epsilon),

        "learning_rate":
            float(agent.get_current_lr()),

        "avg_cpu":
            float(np.mean(avg_cpus)),

        "avg_queue_ms":
            float(np.mean(avg_queues)),

        "avg_energy":
            float(np.mean(avg_energies)),

        "chosen_latency":
            float(np.mean(chosen_latencies)),

        "episode_avg_loss":
            episode_avg_loss,

        "avg_loss_last100":
            float(stats["avg_loss"]),

        "training_steps":
            int(agent.training_steps),

        "episode_time_sec":
            float(episode_time)
    })


    # =================================================
    # Print progress every 10 episodes
    # =================================================
    if (episode + 1) % 10 == 0 or episode == 0:

        print(
            f"Ep {episode+1:3d}/500 | "
            f"R={total_reward:8.1f} | "
            f"RT={avg_rt:7.2f} ms | "
            f"DMR={dmr:.3f} | "
            f"Met={deadline_met_ratio:.3f} | "
            f"ε={epsilon:.3f} | "
            f"Loss={episode_avg_loss:8.2f}"
        )


    # =================================================
    # Save CSV every 10 episodes
    # =================================================
    if (episode + 1) % 10 == 0:

        pd.DataFrame(
            training_rows
        ).to_csv(
            CSV_PATH,
            index=False
        )


    # =================================================
    # Rolling checkpoint every 25 episodes
    # =================================================
    if (
        (episode + 1) % 25 == 0
        or episode == episodes - 1
    ):

        checkpoint = {

            "episode_index":
                episode,

            "epsilon":
                epsilon,

            "policy_net_state_dict":
                agent.policy_net.state_dict(),

            "target_net_state_dict":
                agent.target_net.state_dict(),

            "optimizer_state_dict":
                agent.optimizer.state_dict(),

            "scheduler_state_dict":
                agent.scheduler.state_dict(),

            "training_steps":
                agent.training_steps,

            "losses":
                agent.losses,

            # Replay memory
            "replay_buffer":
                list(agent.memory.buffer),

            # Environment RNG
            "env_rng_state":
                env.rng.bit_generator.state,

            # Random-number states
            "python_random_state":
                random.getstate(),

            "numpy_random_state":
                np.random.get_state(),

            "torch_random_state":
                torch.get_rng_state(),

            "cuda_random_state":
                torch.cuda.get_rng_state_all()
                if torch.cuda.is_available()
                else None,

            "training_rows":
                training_rows,
        }

        torch.save(
            checkpoint,
            CHECKPOINT_PATH
        )

        print(
            f"   💾 Checkpoint saved at episode {episode+1}"
        )


# =====================================================
# 8. Save final CSV
# =====================================================
training_df = pd.DataFrame(
    training_rows
)

training_df.to_csv(
    CSV_PATH,
    index=False
)


# =====================================================
# 9. Save final trained model
# =====================================================
torch.save(
    {
        "policy_net_state_dict":
            agent.policy_net.state_dict(),

        "target_net_state_dict":
            agent.target_net.state_dict(),

        "optimizer_state_dict":
            agent.optimizer.state_dict(),

        "scheduler_state_dict":
            agent.scheduler.state_dict(),

        "training_steps":
            agent.training_steps,

        "final_epsilon":
            epsilon,

        "num_nodes":
            env.num_nodes,

        "state_dim":
            state_dim,

        "action_dim":
            action_dim,
    },
    FINAL_MODEL_PATH
)


# =====================================================
# 10. Final summary
# =====================================================
total_training_time = (
    time.time() - training_start
)

print("\n" + "=" * 100)

print("✅ ORIGINAL ADDQN TRAINING COMPLETE")

print(
    f"Total training time: "
    f"{total_training_time/60:.2f} minutes"
)

print(
    f"Final epsilon: "
    f"{epsilon:.4f}"
)

print(
    f"Replay buffer size: "
    f"{len(agent.memory)}"
)

print(
    f"Training updates: "
    f"{agent.training_steps}"
)

print("\nSaved files:")

print("📊", CSV_PATH)
print("🧠", FINAL_MODEL_PATH)
print("💾", CHECKPOINT_PATH)

print("=" * 100)

import numpy as np
import pandas as pd
import torch
import os

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from ImprovedDQNAgent import ImprovedDQNAgent


# =====================================================
# Load final trained ADDQN
# =====================================================

NUM_NODES = 15
MAX_STEPS = 200
NUM_RUNS = 30

eval_env_temp = ImprovedFogSchedulingEnv(
    num_nodes=NUM_NODES,
    max_steps=MAX_STEPS,
    seed=42
)

state_dim = len(eval_env_temp.reset())
action_dim = NUM_NODES

eval_agent = ImprovedDQNAgent(
    state_dim=state_dim,
    action_dim=action_dim,
    num_nodes=NUM_NODES,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=128,
    use_lr_scheduler=False
)

checkpoint = torch.load(
    FINAL_MODEL_PATH,
    map_location=eval_agent.device
)

eval_agent.policy_net.load_state_dict(
    checkpoint["policy_net_state_dict"]
)

eval_agent.target_net.load_state_dict(
    checkpoint["target_net_state_dict"]
)

eval_agent.policy_net.eval()
eval_agent.target_net.eval()

print("✅ Final ADDQN model loaded")


# =====================================================
# Evaluation function
# =====================================================

def evaluate_addqn(epsilon_eval):

    rows = []

    for run in range(NUM_RUNS):

        seed = 100 + run

        env = ImprovedFogSchedulingEnv(
            num_nodes=NUM_NODES,
            max_steps=MAX_STEPS,
            seed=seed
        )

        state = env.reset()

        response_times = []
        deadline_misses = []
        overloads = []
        rewards = []
        energies = []
        queues = []

        for step in range(env.max_steps):

            action = eval_agent.select_action(
                state,
                epsilon=epsilon_eval
            )

            next_state, reward, done, info = env.step(action)

            response_times.append(
                info["response_time"]
            )

            deadline_misses.append(
                info["deadline_miss"]
            )

            overloads.append(
                info["overload"]
            )

            rewards.append(reward)

            energies.append(
                info["avg_energy"]
            )

            queues.append(
                info["avg_queue_ms"]
            )

            state = next_state

            if done:
                break

        dmr = np.mean(deadline_misses)

        rows.append({
            "run": run + 1,
            "seed": seed,
            "epsilon_eval": epsilon_eval,
            "avg_rt": np.mean(response_times),
            "dmr": dmr,
            "deadline_met_ratio": 1.0 - dmr,
            "overload_ratio": np.mean(overloads),
            "avg_reward": np.mean(rewards),
            "avg_energy": np.mean(energies),
            "avg_queue_ms": np.mean(queues)
        })

    return pd.DataFrame(rows)


# =====================================================
# Evaluate both protocols
# =====================================================

results_eps0 = evaluate_addqn(
    epsilon_eval=0.0
)

results_eps005 = evaluate_addqn(
    epsilon_eval=0.05
)


# =====================================================
# Summary
# =====================================================

def print_summary(df, label):

    print("\n" + "=" * 60)
    print(label)
    print("=" * 60)

    print(
        f"RT:  "
        f"{df['avg_rt'].mean():.2f} ± "
        f"{df['avg_rt'].std(ddof=1):.2f} ms"
    )

    print(
        f"DMR: "
        f"{df['dmr'].mean():.4f} ± "
        f"{df['dmr'].std(ddof=1):.4f}"
    )

    print(
        f"Met: "
        f"{df['deadline_met_ratio'].mean()*100:.2f}% ± "
        f"{df['deadline_met_ratio'].std(ddof=1)*100:.2f}%"
    )

    print(
        f"Overload: "
        f"{df['overload_ratio'].mean():.4f}"
    )

    print(
        f"Avg energy level: "
        f"{df['avg_energy'].mean():.6f}"
    )

    print(
        f"Avg queue: "
        f"{df['avg_queue_ms'].mean():.2f} ms"
    )


print_summary(
    results_eps0,
    "ADDQN Evaluation — epsilon = 0.0"
)

print_summary(
    results_eps005,
    "ADDQN Evaluation — epsilon = 0.05"
)


# =====================================================
# Save raw 30-run results
# =====================================================

results_eps0.to_csv(
    os.path.join(
        SAVE_DIR,
        "ADDQN_eval_30runs_eps0.csv"
    ),
    index=False
)

results_eps005.to_csv(
    os.path.join(
        SAVE_DIR,
        "ADDQN_eval_30runs_eps005.csv"
    ),
    index=False
)

print("\n✅ Both 30-run evaluation files saved.")

# =====================================================
# DIAGNOSTIC:
# Evaluate on the SAME fog topology used during training
# =====================================================

import numpy as np
import pandas as pd

print("🔎 Diagnostic evaluation on training topology")
print("Capacity factors:")
print(env.capacity_factor)

print("\nBase latency:")
print(env.base_latency)

same_topology_rows = []

# IMPORTANT:
# 'env' here is the original training environment
# that completed the 500 training episodes.

for run in range(30):

    state = env.reset()

    response_times = []
    deadline_misses = []

    for step in range(env.max_steps):

        action = eval_agent.select_action(
            state,
            epsilon=0.0
        )

        next_state, reward, done, info = env.step(action)

        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        state = next_state

        if done:
            break

    dmr = np.mean(deadline_misses)

    same_topology_rows.append({
        "run": run + 1,
        "avg_rt": np.mean(response_times),
        "dmr": dmr,
        "deadline_met_ratio": 1.0 - dmr
    })


same_topology_df = pd.DataFrame(
    same_topology_rows
)

print("\n" + "=" * 65)
print("SAME TRAINING TOPOLOGY — 30 evaluation episodes")
print("=" * 65)

print(
    f"RT: "
    f"{same_topology_df['avg_rt'].mean():.2f} ± "
    f"{same_topology_df['avg_rt'].std(ddof=1):.2f} ms"
)

print(
    f"DMR: "
    f"{same_topology_df['dmr'].mean():.4f} ± "
    f"{same_topology_df['dmr'].std(ddof=1):.4f}"
)

print(
    f"Met: "
    f"{same_topology_df['deadline_met_ratio'].mean()*100:.2f}% ± "
    f"{same_topology_df['deadline_met_ratio'].std(ddof=1)*100:.2f}%"
)

