from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from VanillaDQNAgent import VanillaDQNAgent
import numpy as np

# =====================================================
# Vanilla DQN - 5 episode smoke test
# =====================================================

set_global_seed(42)

dqn_test_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

dqn_test_agent = VanillaDQNAgent(
    state_dim=75,
    action_dim=15,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=True
)

episodes = 5

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

batch_size = 64
target_update_freq = 5

print("🧪 Starting Vanilla DQN 5-episode smoke test")
print("=" * 90)

for episode in range(episodes):

    state = dqn_test_env.reset()

    total_reward = 0.0
    response_times = []
    deadline_misses = []
    overloads = []
    episode_losses = []

    for step in range(dqn_test_env.max_steps):

        action = dqn_test_agent.select_action(
            state,
            epsilon
        )

        next_state, reward, done, info = dqn_test_env.step(action)

        dqn_test_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )

        loss = dqn_test_agent.train(
            batch_size=batch_size
        )

        if loss is not None:
            episode_losses.append(loss)

        state = next_state
        total_reward += reward

        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        if done:
            break

    # epsilon decay
    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )

    # target update
    if episode % target_update_freq == 0:
        dqn_test_agent.update_target()

    # scheduler
    dqn_test_agent.step_scheduler()

    avg_rt = np.mean(response_times)
    dmr = np.mean(deadline_misses)
    met_ratio = 1.0 - dmr
    overload_ratio = np.mean(overloads)

    avg_loss = (
        np.mean(episode_losses)
        if len(episode_losses) > 0
        else 0.0
    )

    print(
        f"Episode {episode+1:2d} | "
        f"Reward={total_reward:8.2f} | "
        f"RT={avg_rt:7.2f} ms | "
        f"DMR={dmr:.3f} | "
        f"Met={met_ratio:.3f} | "
        f"Overload={overload_ratio:.3f} | "
        f"Loss={avg_loss:8.3f} | "
        f"Epsilon={epsilon:.3f}"
    )

print("=" * 90)
print("✅ Vanilla DQN smoke test completed")
print("Replay buffer:", len(dqn_test_agent.memory))
print("Training updates:", dqn_test_agent.training_steps)

import os
import time
import random
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from VanillaDQNAgent import VanillaDQNAgent


# =====================================================
# 1. Reproducibility
# =====================================================
set_global_seed(42)


# =====================================================
# 2. Output files
# =====================================================
DQN_CSV_PATH = os.path.join(
    SAVE_DIR,
    "Vanilla_DQN_training_500episodes.csv"
)

DQN_CHECKPOINT_PATH = os.path.join(
    SAVE_DIR,
    "Vanilla_DQN_rolling_checkpoint.pt"
)

DQN_FINAL_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "Vanilla_DQN_final_model.pth"
)


# =====================================================
# 3. Fresh Environment
# SAME environment settings as ADDQN
# =====================================================
dqn_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

state_dim = len(dqn_env.reset())
action_dim = dqn_env.num_nodes


# =====================================================
# 4. Fresh Vanilla DQN Agent
# =====================================================
dqn_agent = VanillaDQNAgent(
    state_dim=state_dim,
    action_dim=action_dim,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=True
)


# =====================================================
# 5. SAME Training Hyperparameters as ADDQN
# =====================================================
episodes = 500

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

batch_size = 64
target_update_freq = 5


# =====================================================
# 6. Training Log
# =====================================================
dqn_training_rows = []

print("🚀 Starting VANILLA DQN training")
print("Episodes:", episodes)
print("Steps per episode:", dqn_env.max_steps)
print("Expected interactions:", episodes * dqn_env.max_steps)
print("Parameters:", sum(p.numel() for p in dqn_agent.policy_net.parameters()))
print("Device:", dqn_agent.device)
print("=" * 100)

training_start = time.time()


# =====================================================
# 7. Training Loop
# =====================================================
for episode in range(episodes):

    episode_start = time.time()

    state = dqn_env.reset()

    total_reward = 0.0

    response_times = []
    deadline_misses = []
    overloads = []

    avg_cpus = []
    avg_queues = []
    avg_energies = []
    chosen_latencies = []

    episode_losses = []

    for step in range(dqn_env.max_steps):

        # Select action
        action = dqn_agent.select_action(
            state,
            epsilon
        )

        # Environment step
        next_state, reward, done, info = dqn_env.step(action)

        # Store experience
        dqn_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )

        # Train
        loss = dqn_agent.train(
            batch_size=batch_size
        )

        if loss is not None:
            episode_losses.append(loss)

        state = next_state
        total_reward += reward

        # Metrics
        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        avg_cpus.append(
            info["avg_cpu"]
        )

        avg_queues.append(
            info["avg_queue_ms"]
        )

        avg_energies.append(
            info["avg_energy"]
        )

        chosen_latencies.append(
            info["latency"]
        )

        if done:
            break


    # =================================================
    # End of episode
    # =================================================

    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )

    # SAME target-update schedule used for ADDQN
    if episode % target_update_freq == 0:
        dqn_agent.update_target()

    dqn_agent.step_scheduler()


    # =================================================
    # Metrics
    # =================================================
    avg_rt = float(
        np.mean(response_times)
    )

    dmr = float(
        np.mean(deadline_misses)
    )

    deadline_met_ratio = float(
        1.0 - dmr
    )

    overload_ratio = float(
        np.mean(overloads)
    )

    episode_avg_loss = (
        float(np.mean(episode_losses))
        if len(episode_losses) > 0
        else 0.0
    )

    stats = dqn_agent.get_training_stats()

    episode_time = (
        time.time() - episode_start
    )


    dqn_training_rows.append({

        "episode": episode + 1,

        "total_reward":
            float(total_reward),

        "avg_rt":
            avg_rt,

        "dmr":
            dmr,

        "deadline_met_ratio":
            deadline_met_ratio,

        "overload_ratio":
            overload_ratio,

        "epsilon":
            float(epsilon),

        "learning_rate":
            float(dqn_agent.get_current_lr()),

        "avg_cpu":
            float(np.mean(avg_cpus)),

        "avg_queue_ms":
            float(np.mean(avg_queues)),

        "avg_energy":
            float(np.mean(avg_energies)),

        "chosen_latency":
            float(np.mean(chosen_latencies)),

        "episode_avg_loss":
            episode_avg_loss,

        "avg_loss_last100":
            float(stats["avg_loss"]),

        "training_steps":
            int(dqn_agent.training_steps),

        "episode_time_sec":
            float(episode_time)
    })


    # =================================================
    # Progress every 10 episodes
    # =================================================
    if (episode + 1) % 10 == 0 or episode == 0:

        print(
            f"Ep {episode+1:3d}/500 | "
            f"R={total_reward:8.1f} | "
            f"RT={avg_rt:7.2f} ms | "
            f"DMR={dmr:.3f} | "
            f"Met={deadline_met_ratio:.3f} | "
            f"ε={epsilon:.3f} | "
            f"Loss={episode_avg_loss:8.2f}"
        )


    # =================================================
    # Save CSV every 10 episodes
    # =================================================
    if (episode + 1) % 10 == 0:

        pd.DataFrame(
            dqn_training_rows
        ).to_csv(
            DQN_CSV_PATH,
            index=False
        )


    # =================================================
    # Checkpoint every 25 episodes
    # =================================================
    if (
        (episode + 1) % 25 == 0
        or episode == episodes - 1
    ):

        checkpoint = {

            "episode_index":
                episode,

            "epsilon":
                epsilon,

            "policy_net_state_dict":
                dqn_agent.policy_net.state_dict(),

            "target_net_state_dict":
                dqn_agent.target_net.state_dict(),

            "optimizer_state_dict":
                dqn_agent.optimizer.state_dict(),

            "scheduler_state_dict":
                dqn_agent.scheduler.state_dict(),

            "training_steps":
                dqn_agent.training_steps,

            "losses":
                dqn_agent.losses,

            "replay_buffer":
                list(dqn_agent.memory.buffer),

            "env_rng_state":
                dqn_env.rng.bit_generator.state,

            "python_random_state":
                random.getstate(),

            "numpy_random_state":
                np.random.get_state(),

            "torch_random_state":
                torch.get_rng_state(),

            "cuda_random_state":
                torch.cuda.get_rng_state_all()
                if torch.cuda.is_available()
                else None,

            "training_rows":
                dqn_training_rows
        }

        torch.save(
            checkpoint,
            DQN_CHECKPOINT_PATH
        )

        print(
            f"   💾 DQN checkpoint saved at episode {episode+1}"
        )


# =====================================================
# 8. Save final CSV
# =====================================================
dqn_training_df = pd.DataFrame(
    dqn_training_rows
)

dqn_training_df.to_csv(
    DQN_CSV_PATH,
    index=False
)


# =====================================================
# 9. Save final model
# =====================================================
torch.save(
    {
        "policy_net_state_dict":
            dqn_agent.policy_net.state_dict(),

        "target_net_state_dict":
            dqn_agent.target_net.state_dict(),

        "optimizer_state_dict":
            dqn_agent.optimizer.state_dict(),

        "scheduler_state_dict":
            dqn_agent.scheduler.state_dict(),

        "training_steps":
            dqn_agent.training_steps,

        "final_epsilon":
            epsilon,

        "state_dim":
            state_dim,

        "action_dim":
            action_dim,

        "hidden_dim":
            256
    },
    DQN_FINAL_MODEL_PATH
)


# =====================================================
# 10. Final Summary
# =====================================================
total_training_time = (
    time.time() - training_start
)

print("\n" + "=" * 100)

print("✅ VANILLA DQN TRAINING COMPLETE")

print(
    f"Total training time: "
    f"{total_training_time/60:.2f} minutes"
)

print(
    f"Final epsilon: "
    f"{epsilon:.4f}"
)

print(
    f"Replay buffer size: "
    f"{len(dqn_agent.memory)}"
)

print(
    f"Training updates: "
    f"{dqn_agent.training_steps}"
)

print("\nSaved files:")

print("📊", DQN_CSV_PATH)
print("🧠", DQN_FINAL_MODEL_PATH)
print("💾", DQN_CHECKPOINT_PATH)

print("=" * 100)

import os
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from ImprovedDQNAgent import ImprovedDQNAgent
from VanillaDQNAgent import VanillaDQNAgent


# =====================================================
# Configuration
# =====================================================

NUM_NODES = 15
MAX_STEPS = 200
NUM_RUNS = 30

TOPOLOGY_SEED = 42

STATE_DIM = NUM_NODES * 5
ACTION_DIM = NUM_NODES


# =====================================================
# Load trained ADDQN
# =====================================================

addqn_eval_agent = ImprovedDQNAgent(
    state_dim=STATE_DIM,
    action_dim=ACTION_DIM,
    num_nodes=NUM_NODES,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=128,
    use_lr_scheduler=False
)

addqn_ckpt = torch.load(
    FINAL_MODEL_PATH,
    map_location=addqn_eval_agent.device
)

addqn_eval_agent.policy_net.load_state_dict(
    addqn_ckpt["policy_net_state_dict"]
)

addqn_eval_agent.policy_net.eval()


# =====================================================
# Load trained Vanilla DQN
# =====================================================

dqn_eval_agent = VanillaDQNAgent(
    state_dim=STATE_DIM,
    action_dim=ACTION_DIM,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=False
)

dqn_ckpt = torch.load(
    DQN_FINAL_MODEL_PATH,
    map_location=dqn_eval_agent.device
)

dqn_eval_agent.policy_net.load_state_dict(
    dqn_ckpt["policy_net_state_dict"]
)

dqn_eval_agent.policy_net.eval()


print("✅ ADDQN and Vanilla DQN loaded")


# =====================================================
# Matched fixed-topology evaluation
# =====================================================

def evaluate_fixed_topology(agent, method_name):

    rows = []

    for run in range(NUM_RUNS):

        task_seed = 100 + run

        # ---------------------------------------------
        # Always create SAME topology from seed 42
        # ---------------------------------------------
        env = ImprovedFogSchedulingEnv(
            num_nodes=NUM_NODES,
            max_steps=MAX_STEPS,
            seed=TOPOLOGY_SEED
        )

        # ---------------------------------------------
        # Keep topology fixed, but give this run
        # a NEW independent task stream.
        # ---------------------------------------------
        env.rng = np.random.default_rng(
            task_seed
        )

        state = env.reset()

        response_times = []
        deadline_misses = []
        overloads = []
        rewards = []

        # Additional reviewer-requested metrics
        queue_imbalance = []

        for step in range(env.max_steps):

            action = agent.select_action(
                state,
                epsilon=0.0
            )

            next_state, reward, done, info = env.step(action)

            response_times.append(
                info["response_time"]
            )

            deadline_misses.append(
                info["deadline_miss"]
            )

            overloads.append(
                info["overload"]
            )

            rewards.append(
                reward
            )

            # Normalized queue dispersion
            queue_imbalance.append(
                np.std(env.queue_ms)
                / env.queue_cap_ms
            )

            state = next_state

            if done:
                break

        # ---------------------------------------------
        # Energy proxy
        # Initial energy = 1 for every node
        # ---------------------------------------------
        total_energy_depletion = float(
            np.sum(
                1.0 - env.energy
            )
        )

        dmr = float(
            np.mean(deadline_misses)
        )

        rows.append({

            "run": run + 1,

            "task_seed": task_seed,

            "method": method_name,

            "avg_rt":
                float(np.mean(response_times)),

            "dmr":
                dmr,

            "deadline_met_ratio":
                float(1.0 - dmr),

            "overload_ratio":
                float(np.mean(overloads)),

            "avg_reward":
                float(np.mean(rewards)),

            "energy_depletion":
                total_energy_depletion,

            "final_avg_energy":
                float(np.mean(env.energy)),

            "load_imbalance":
                float(np.mean(queue_imbalance))
        })

    return pd.DataFrame(rows)


# =====================================================
# Run both methods
# =====================================================

addqn_matched = evaluate_fixed_topology(
    addqn_eval_agent,
    "ADDQN"
)

dqn_matched = evaluate_fixed_topology(
    dqn_eval_agent,
    "Vanilla DQN"
)


# =====================================================
# Summary function
# =====================================================

def show_summary(df):

    name = df["method"].iloc[0]

    print("\n" + "=" * 70)
    print(name)
    print("=" * 70)

    print(
        f"RT: "
        f"{df['avg_rt'].mean():.2f} ± "
        f"{df['avg_rt'].std(ddof=1):.2f} ms"
    )

    print(
        f"DMR: "
        f"{df['dmr'].mean():.4f} ± "
        f"{df['dmr'].std(ddof=1):.4f}"
    )

    print(
        f"Deadline Met: "
        f"{df['deadline_met_ratio'].mean()*100:.2f}% ± "
        f"{df['deadline_met_ratio'].std(ddof=1)*100:.2f}%"
    )

    print(
        f"Energy depletion: "
        f"{df['energy_depletion'].mean():.6f} ± "
        f"{df['energy_depletion'].std(ddof=1):.6f}"
    )

    print(
        f"Load imbalance: "
        f"{df['load_imbalance'].mean():.6f} ± "
        f"{df['load_imbalance'].std(ddof=1):.6f}"
    )

    print(
        f"Overload ratio: "
        f"{df['overload_ratio'].mean():.4f}"
    )


show_summary(addqn_matched)
show_summary(dqn_matched)


# =====================================================
# Save RAW paired results
# =====================================================

addqn_matched.to_csv(
    os.path.join(
        SAVE_DIR,
        "ADDQN_fixed_topology_30runs.csv"
    ),
    index=False
)

dqn_matched.to_csv(
    os.path.join(
        SAVE_DIR,
        "Vanilla_DQN_fixed_topology_30runs.csv"
    ),
    index=False
)

combined_first_comparison = pd.concat(
    [
        addqn_matched,
        dqn_matched
    ],
    ignore_index=True
)

combined_first_comparison.to_csv(
    os.path.join(
        SAVE_DIR,
        "ADDQN_vs_DQN_matched_30runs.csv"
    ),
    index=False
)

print("\n✅ Matched raw evaluation files saved.")

from scipy import stats
import numpy as np
import pandas as pd
import os


# =====================================================
# Paired statistical analysis:
# ADDQN vs Vanilla DQN
# =====================================================

metrics = {
    "avg_rt": "Response Time (ms)",
    "dmr": "Deadline Miss Ratio",
    "energy_depletion": "Normalized Energy Depletion",
    "load_imbalance": "Load Imbalance"
}

stat_rows = []


def cohens_dz(x, y):
    """
    Cohen's dz for paired samples.
    """
    diff = x - y

    return float(
        np.mean(diff)
        /
        np.std(diff, ddof=1)
    )


def paired_ci95(x, y):
    """
    95% confidence interval
    for the paired mean difference:
    ADDQN - DQN
    """
    diff = x - y

    mean_diff = np.mean(diff)

    se = stats.sem(diff)

    ci_low, ci_high = stats.t.interval(
        confidence=0.95,
        df=len(diff) - 1,
        loc=mean_diff,
        scale=se
    )

    return (
        float(mean_diff),
        float(ci_low),
        float(ci_high)
    )


for metric, label in metrics.items():

    # Same ordering of matched task seeds
    x = (
        addqn_matched
        .sort_values("task_seed")[metric]
        .to_numpy()
    )

    y = (
        dqn_matched
        .sort_values("task_seed")[metric]
        .to_numpy()
    )

    diff = x - y

    # ---------------------------------------------
    # Normality of paired differences
    # ---------------------------------------------
    shapiro_stat, shapiro_p = stats.shapiro(
        diff
    )

    # ---------------------------------------------
    # Paired t-test
    # ---------------------------------------------
    t_stat, t_p = stats.ttest_rel(
        x,
        y
    )

    # ---------------------------------------------
    # Wilcoxon signed-rank test
    # ---------------------------------------------
    try:
        w_stat, w_p = stats.wilcoxon(
            x,
            y,
            alternative="two-sided"
        )
    except ValueError:
        w_stat = np.nan
        w_p = np.nan

    # ---------------------------------------------
    # Effect size
    # ---------------------------------------------
    d = cohens_dz(
        x,
        y
    )

    # ---------------------------------------------
    # 95% CI
    # ---------------------------------------------
    mean_diff, ci_low, ci_high = paired_ci95(
        x,
        y
    )

    # ---------------------------------------------
    # Relative improvement
    # For RT / DMR / Energy / Load:
    # lower is better
    # ---------------------------------------------
    relative_improvement = (
        (np.mean(y) - np.mean(x))
        /
        np.mean(y)
        *
        100
    )

    stat_rows.append({

        "Metric":
            label,

        "ADDQN_mean":
            np.mean(x),

        "DQN_mean":
            np.mean(y),

        "Mean_difference_ADDQN_minus_DQN":
            mean_diff,

        "CI95_low":
            ci_low,

        "CI95_high":
            ci_high,

        "Shapiro_p":
            shapiro_p,

        "Paired_t":
            t_stat,

        "Paired_t_p":
            t_p,

        "Wilcoxon_W":
            w_stat,

        "Wilcoxon_p":
            w_p,

        "Cohens_dz":
            d,

        "Relative_improvement_percent":
            relative_improvement
    })


stats_addqn_vs_dqn = pd.DataFrame(
    stat_rows
)


# =====================================================
# Display
# =====================================================

pd.set_option(
    "display.max_columns",
    None
)

print(
    "📊 ADDQN vs Vanilla DQN "
    "— Paired Statistical Analysis"
)

display(
    stats_addqn_vs_dqn.round(6)
)


# =====================================================
# Simple interpretation
# =====================================================

print("\n" + "=" * 80)

for _, row in stats_addqn_vs_dqn.iterrows():

    print(
        f"\n{row['Metric']}"
    )

    print(
        f"ADDQN: {row['ADDQN_mean']:.6f}"
    )

    print(
        f"DQN:   {row['DQN_mean']:.6f}"
    )

    print(
        f"Mean difference "
        f"(ADDQN-DQN): "
        f"{row['Mean_difference_ADDQN_minus_DQN']:.6f}"
    )

    print(
        f"95% CI: "
        f"[{row['CI95_low']:.6f}, "
        f"{row['CI95_high']:.6f}]"
    )

    print(
        f"Shapiro p: "
        f"{row['Shapiro_p']:.6g}"
    )

    print(
        f"Paired t-test p: "
        f"{row['Paired_t_p']:.6g}"
    )

    print(
        f"Wilcoxon p: "
        f"{row['Wilcoxon_p']:.6g}"
    )

    print(
        f"Cohen's dz: "
        f"{row['Cohens_dz']:.3f}"
    )

    print(
        f"Relative improvement: "
        f"{row['Relative_improvement_percent']:.2f}%"
    )


# =====================================================
# Save results
# =====================================================

STATS_DQN_PATH = os.path.join(
    SAVE_DIR,
    "stats_ADDQN_vs_Vanilla_DQN.csv"
)

stats_addqn_vs_dqn.to_csv(
    STATS_DQN_PATH,
    index=False
)

print(
    "\n✅ Statistical results saved:"
)

print(
    STATS_DQN_PATH
)

