print(THREE_METHOD_PATH)

from scipy import stats
import numpy as np
import pandas as pd
import os


# =====================================================
# ADDQN vs Vanilla DDQN
# Paired statistical analysis
# =====================================================

metrics = {
    "avg_rt": "Response Time (ms)",
    "dmr": "Deadline Miss Ratio",
    "energy_depletion": "Normalized Energy Depletion",
    "load_imbalance": "Load Imbalance"
}

rows = []


for metric, label in metrics.items():

    x = (
        addqn_matched
        .sort_values("task_seed")[metric]
        .to_numpy()
    )

    y = (
        ddqn_matched
        .sort_values("task_seed")[metric]
        .to_numpy()
    )

    # ADDQN - DDQN
    diff = x - y

    # Normality of paired differences
    shapiro_stat, shapiro_p = stats.shapiro(diff)

    # Paired t-test
    t_stat, t_p = stats.ttest_rel(x, y)

    # Wilcoxon
    try:
        w_stat, w_p = stats.wilcoxon(
            x,
            y,
            alternative="two-sided"
        )
    except ValueError:
        w_stat = np.nan
        w_p = np.nan

    # Cohen's dz
    diff_sd = np.std(diff, ddof=1)

    cohens_dz = (
        np.mean(diff) / diff_sd
        if diff_sd > 0
        else np.nan
    )

    # 95% CI
    mean_diff = np.mean(diff)

    se = stats.sem(diff)

    ci_low, ci_high = stats.t.interval(
        confidence=0.95,
        df=len(diff) - 1,
        loc=mean_diff,
        scale=se
    )

    # Lower is better for all four metrics
    relative_improvement_addqn = (
        (np.mean(y) - np.mean(x))
        /
        np.mean(y)
        *
        100
    )

    rows.append({

        "Metric": label,

        "ADDQN_mean":
            np.mean(x),

        "DDQN_mean":
            np.mean(y),

        "Mean_difference_ADDQN_minus_DDQN":
            mean_diff,

        "CI95_low":
            ci_low,

        "CI95_high":
            ci_high,

        "Shapiro_p":
            shapiro_p,

        "Paired_t":
            t_stat,

        "Paired_t_p":
            t_p,

        "Wilcoxon_W":
            w_stat,

        "Wilcoxon_p":
            w_p,

        "Cohens_dz":
            cohens_dz,

        "Relative_improvement_ADDQN_percent":
            relative_improvement_addqn
    })


stats_addqn_vs_ddqn = pd.DataFrame(rows)

pd.set_option(
    "display.max_columns",
    None
)

print(
    "📊 ADDQN vs Vanilla DDQN "
    "— Paired Statistical Analysis"
)

display(
    stats_addqn_vs_ddqn.round(6)
)


# =====================================================
# Readable output
# =====================================================

print("\n" + "=" * 85)

for _, row in stats_addqn_vs_ddqn.iterrows():

    print(
        f"\n{row['Metric']}"
    )

    print(
        f"ADDQN: {row['ADDQN_mean']:.6f}"
    )

    print(
        f"DDQN:  {row['DDQN_mean']:.6f}"
    )

    print(
        f"Difference (ADDQN-DDQN): "
        f"{row['Mean_difference_ADDQN_minus_DDQN']:.6f}"
    )

    print(
        f"95% CI: "
        f"[{row['CI95_low']:.6f}, "
        f"{row['CI95_high']:.6f}]"
    )

    print(
        f"Shapiro p: "
        f"{row['Shapiro_p']:.6g}"
    )

    print(
        f"Paired t-test p: "
        f"{row['Paired_t_p']:.6g}"
    )

    print(
        f"Wilcoxon p: "
        f"{row['Wilcoxon_p']:.6g}"
    )

    print(
        f"Cohen's dz: "
        f"{row['Cohens_dz']:.3f}"
    )

    print(
        f"ADDQN relative improvement: "
        f"{row['Relative_improvement_ADDQN_percent']:.2f}%"
    )


# =====================================================
# Save
# =====================================================

STATS_ADDQN_DDQN_PATH = os.path.join(
    SAVE_DIR,
    "stats_ADDQN_vs_Vanilla_DDQN.csv"
)

stats_addqn_vs_ddqn.to_csv(
    STATS_ADDQN_DDQN_PATH,
    index=False
)

print("\n✅ Saved:")
print(STATS_ADDQN_DDQN_PATH)

from scipy import stats
import numpy as np
import pandas as pd
import os


# =====================================================
# Vanilla DQN vs Vanilla DDQN
# =====================================================

metrics = {
    "avg_rt": "Response Time (ms)",
    "dmr": "Deadline Miss Ratio",
    "energy_depletion": "Normalized Energy Depletion",
    "load_imbalance": "Load Imbalance"
}

rows = []

for metric, label in metrics.items():

    dqn_values = (
        dqn_matched
        .sort_values("task_seed")[metric]
        .to_numpy()
    )

    ddqn_values = (
        ddqn_matched
        .sort_values("task_seed")[metric]
        .to_numpy()
    )

    # DQN - DDQN
    diff = dqn_values - ddqn_values

    # Normality
    shapiro_stat, shapiro_p = stats.shapiro(diff)

    # Paired t-test
    t_stat, t_p = stats.ttest_rel(
        dqn_values,
        ddqn_values
    )

    # Wilcoxon
    try:
        w_stat, w_p = stats.wilcoxon(
            dqn_values,
            ddqn_values,
            alternative="two-sided"
        )
    except ValueError:
        w_stat = np.nan
        w_p = np.nan

    # Cohen's dz
    diff_sd = np.std(diff, ddof=1)

    dz = (
        np.mean(diff) / diff_sd
        if diff_sd > 0
        else np.nan
    )

    # 95% CI
    mean_diff = np.mean(diff)

    ci_low, ci_high = stats.t.interval(
        confidence=0.95,
        df=len(diff) - 1,
        loc=mean_diff,
        scale=stats.sem(diff)
    )

    # Lower is better
    ddqn_improvement = (
        (np.mean(dqn_values) - np.mean(ddqn_values))
        / np.mean(dqn_values)
        * 100
    )

    rows.append({
        "Metric": label,
        "DQN_mean": np.mean(dqn_values),
        "DDQN_mean": np.mean(ddqn_values),
        "Mean_difference_DQN_minus_DDQN": mean_diff,
        "CI95_low": ci_low,
        "CI95_high": ci_high,
        "Shapiro_p": shapiro_p,
        "Paired_t": t_stat,
        "Paired_t_p": t_p,
        "Wilcoxon_W": w_stat,
        "Wilcoxon_p": w_p,
        "Cohens_dz": dz,
        "DDQN_improvement_percent": ddqn_improvement
    })


stats_dqn_vs_ddqn = pd.DataFrame(rows)

pd.set_option("display.max_columns", None)

print(
    "📊 Vanilla DQN vs Vanilla DDQN "
    "— Paired Statistical Analysis"
)

display(
    stats_dqn_vs_ddqn.round(6)
)


# =====================================================
# Save
# =====================================================

DQN_DDQN_STATS_PATH = os.path.join(
    SAVE_DIR,
    "stats_Vanilla_DQN_vs_Vanilla_DDQN.csv"
)

stats_dqn_vs_ddqn.to_csv(
    DQN_DDQN_STATS_PATH,
    index=False
)

print("\n✅ Saved:")
print(DQN_DDQN_STATS_PATH)

