from DuelingDQNAgent import DuelingDQNAgent
import numpy as np

dueling_agent = DuelingDQNAgent(
    state_dim=75,
    action_dim=15,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=True
)

print("✅ Dueling DQN Agent loaded")
print("Device:", dueling_agent.device)

print(
    "Policy parameters:",
    sum(
        p.numel()
        for p in dueling_agent.policy_net.parameters()
    )
)

test_state = np.zeros(
    75,
    dtype=np.float32
)

action = dueling_agent.select_action(
    test_state,
    epsilon=0.0
)

print("Greedy test action:", action)
print(
    "Initial learning rate:",
    dueling_agent.get_current_lr()
)

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from DuelingDQNAgent import DuelingDQNAgent
import numpy as np

# =====================================================
# Dueling DQN - 5 episode smoke test
# =====================================================

set_global_seed(42)

dueling_test_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

dueling_test_agent = DuelingDQNAgent(
    state_dim=75,
    action_dim=15,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=True
)

episodes = 5

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

batch_size = 64
target_update_freq = 5

print("🧪 Starting Dueling DQN 5-episode smoke test")
print("=" * 90)

for episode in range(episodes):

    state = dueling_test_env.reset()

    total_reward = 0.0
    response_times = []
    deadline_misses = []
    overloads = []
    episode_losses = []

    for step in range(dueling_test_env.max_steps):

        action = dueling_test_agent.select_action(
            state,
            epsilon
        )

        next_state, reward, done, info = (
            dueling_test_env.step(action)
        )

        dueling_test_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )

        loss = dueling_test_agent.train(
            batch_size=batch_size
        )

        if loss is not None:
            episode_losses.append(loss)

        state = next_state
        total_reward += reward

        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        if done:
            break

    # Epsilon decay
    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )

    # Target update
    if episode % target_update_freq == 0:
        dueling_test_agent.update_target()

    # LR scheduler
    dueling_test_agent.step_scheduler()

    avg_rt = np.mean(response_times)
    dmr = np.mean(deadline_misses)
    met_ratio = 1.0 - dmr
    overload_ratio = np.mean(overloads)

    avg_loss = (
        np.mean(episode_losses)
        if len(episode_losses) > 0
        else 0.0
    )

    print(
        f"Episode {episode+1:2d} | "
        f"Reward={total_reward:8.2f} | "
        f"RT={avg_rt:7.2f} ms | "
        f"DMR={dmr:.3f} | "
        f"Met={met_ratio:.3f} | "
        f"Overload={overload_ratio:.3f} | "
        f"Loss={avg_loss:8.3f} | "
        f"Epsilon={epsilon:.3f}"
    )

print("=" * 90)
print("✅ Dueling DQN smoke test completed")
print("Replay buffer:", len(dueling_test_agent.memory))
print("Training updates:", dueling_test_agent.training_steps)

import os
import time
import random
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from DuelingDQNAgent import DuelingDQNAgent


# =====================================================
# 1. Reproducibility
# =====================================================

set_global_seed(42)


# =====================================================
# 2. Output paths
# =====================================================

DUELING_CSV_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DQN_training_500episodes.csv"
)

DUELING_CHECKPOINT_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DQN_rolling_checkpoint.pt"
)

DUELING_FINAL_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DQN_final_model.pth"
)


# =====================================================
# 3. Environment
# SAME protocol as previous models
# =====================================================

dueling_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

state_dim = len(
    dueling_env.reset()
)

action_dim = dueling_env.num_nodes


# =====================================================
# 4. Fresh Dueling DQN Agent
# =====================================================

dueling_agent = DuelingDQNAgent(
    state_dim=state_dim,
    action_dim=action_dim,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=True
)


# =====================================================
# 5. Training hyperparameters
# =====================================================

episodes = 500

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

batch_size = 64
target_update_freq = 5


# =====================================================
# 6. Training log
# =====================================================

dueling_training_rows = []

print("🚀 Starting DUELING DQN training")
print("Episodes:", episodes)
print("Steps per episode:", dueling_env.max_steps)
print(
    "Expected interactions:",
    episodes * dueling_env.max_steps
)

print(
    "Parameters:",
    sum(
        p.numel()
        for p in dueling_agent.policy_net.parameters()
    )
)

print("Device:", dueling_agent.device)
print("=" * 100)

training_start = time.time()


# =====================================================
# 7. Training loop
# =====================================================

for episode in range(episodes):

    episode_start = time.time()

    state = dueling_env.reset()

    total_reward = 0.0

    response_times = []
    deadline_misses = []
    overloads = []

    avg_cpus = []
    avg_queues = []
    avg_energies = []
    chosen_latencies = []

    episode_losses = []


    for step in range(
        dueling_env.max_steps
    ):

        # ---------------------------------------------
        # Select action
        # ---------------------------------------------
        action = dueling_agent.select_action(
            state,
            epsilon
        )

        # ---------------------------------------------
        # Environment interaction
        # ---------------------------------------------
        next_state, reward, done, info = (
            dueling_env.step(action)
        )

        # ---------------------------------------------
        # Replay buffer
        # ---------------------------------------------
        dueling_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )

        # ---------------------------------------------
        # Training update
        # ---------------------------------------------
        loss = dueling_agent.train(
            batch_size=batch_size
        )

        if loss is not None:
            episode_losses.append(
                loss
            )

        state = next_state
        total_reward += reward


        # ---------------------------------------------
        # Metrics
        # ---------------------------------------------
        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        avg_cpus.append(
            info["avg_cpu"]
        )

        avg_queues.append(
            info["avg_queue_ms"]
        )

        avg_energies.append(
            info["avg_energy"]
        )

        chosen_latencies.append(
            info["latency"]
        )

        if done:
            break


    # =================================================
    # End of episode
    # =================================================

    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )

    # Same target-update schedule
    if episode % target_update_freq == 0:
        dueling_agent.update_target()

    dueling_agent.step_scheduler()


    # =================================================
    # Episode metrics
    # =================================================

    avg_rt = float(
        np.mean(response_times)
    )

    dmr = float(
        np.mean(deadline_misses)
    )

    deadline_met_ratio = float(
        1.0 - dmr
    )

    overload_ratio = float(
        np.mean(overloads)
    )

    episode_avg_loss = (
        float(
            np.mean(
                episode_losses
            )
        )
        if len(episode_losses) > 0
        else 0.0
    )

    stats = (
        dueling_agent
        .get_training_stats()
    )

    episode_time = (
        time.time()
        - episode_start
    )


    dueling_training_rows.append({

        "episode":
            episode + 1,

        "total_reward":
            float(total_reward),

        "avg_rt":
            avg_rt,

        "dmr":
            dmr,

        "deadline_met_ratio":
            deadline_met_ratio,

        "overload_ratio":
            overload_ratio,

        "epsilon":
            float(epsilon),

        "learning_rate":
            float(
                dueling_agent
                .get_current_lr()
            ),

        "avg_cpu":
            float(
                np.mean(avg_cpus)
            ),

        "avg_queue_ms":
            float(
                np.mean(avg_queues)
            ),

        "avg_energy":
            float(
                np.mean(avg_energies)
            ),

        "chosen_latency":
            float(
                np.mean(
                    chosen_latencies
                )
            ),

        "episode_avg_loss":
            episode_avg_loss,

        "avg_loss_last100":
            float(
                stats["avg_loss"]
            ),

        "training_steps":
            int(
                dueling_agent
                .training_steps
            ),

        "episode_time_sec":
            float(
                episode_time
            )
    })


    # =================================================
    # Progress
    # =================================================

    if (
        (episode + 1) % 10 == 0
        or episode == 0
    ):

        print(
            f"Ep {episode+1:3d}/500 | "
            f"R={total_reward:8.1f} | "
            f"RT={avg_rt:7.2f} ms | "
            f"DMR={dmr:.3f} | "
            f"Met={deadline_met_ratio:.3f} | "
            f"ε={epsilon:.3f} | "
            f"Loss={episode_avg_loss:8.2f}"
        )


    # =================================================
    # Save CSV every 10 episodes
    # =================================================

    if (episode + 1) % 10 == 0:

        pd.DataFrame(
            dueling_training_rows
        ).to_csv(
            DUELING_CSV_PATH,
            index=False
        )


    # =================================================
    # Checkpoint every 25 episodes
    # =================================================

    if (
        (episode + 1) % 25 == 0
        or episode == episodes - 1
    ):

        checkpoint = {

            "episode_index":
                episode,

            "epsilon":
                epsilon,

            "policy_net_state_dict":
                dueling_agent
                .policy_net
                .state_dict(),

            "target_net_state_dict":
                dueling_agent
                .target_net
                .state_dict(),

            "optimizer_state_dict":
                dueling_agent
                .optimizer
                .state_dict(),

            "scheduler_state_dict":
                dueling_agent
                .scheduler
                .state_dict(),

            "training_steps":
                dueling_agent
                .training_steps,

            "losses":
                dueling_agent
                .losses,

            "replay_buffer":
                list(
                    dueling_agent
                    .memory
                    .buffer
                ),

            "env_rng_state":
                dueling_env
                .rng
                .bit_generator
                .state,

            "python_random_state":
                random.getstate(),

            "numpy_random_state":
                np.random.get_state(),

            "torch_random_state":
                torch.get_rng_state(),

            "cuda_random_state":
                (
                    torch.cuda
                    .get_rng_state_all()
                    if torch.cuda.is_available()
                    else None
                ),

            "training_rows":
                dueling_training_rows
        }

        torch.save(
            checkpoint,
            DUELING_CHECKPOINT_PATH
        )

        print(
            f"   💾 Dueling checkpoint "
            f"saved at episode "
            f"{episode+1}"
        )


# =====================================================
# 8. Save final training CSV
# =====================================================

dueling_training_df = pd.DataFrame(
    dueling_training_rows
)

dueling_training_df.to_csv(
    DUELING_CSV_PATH,
    index=False
)


# =====================================================
# 9. Save final model
# =====================================================

torch.save(
    {

        "policy_net_state_dict":
            dueling_agent
            .policy_net
            .state_dict(),

        "target_net_state_dict":
            dueling_agent
            .target_net
            .state_dict(),

        "optimizer_state_dict":
            dueling_agent
            .optimizer
            .state_dict(),

        "scheduler_state_dict":
            dueling_agent
            .scheduler
            .state_dict(),

        "training_steps":
            dueling_agent
            .training_steps,

        "final_epsilon":
            epsilon,

        "state_dim":
            state_dim,

        "action_dim":
            action_dim,

        "hidden_dim":
            256,

        "algorithm":
            "Dueling DQN with standard DQN target"
    },

    DUELING_FINAL_MODEL_PATH
)


# =====================================================
# 10. Final summary
# =====================================================

total_training_time = (
    time.time()
    - training_start
)

print("\n" + "=" * 100)

print(
    "✅ DUELING DQN TRAINING COMPLETE"
)

print(
    f"Total training time: "
    f"{total_training_time/60:.2f} minutes"
)

print(
    f"Final epsilon: "
    f"{epsilon:.4f}"
)

print(
    f"Replay buffer size: "
    f"{len(dueling_agent.memory)}"
)

print(
    f"Training updates: "
    f"{dueling_agent.training_steps}"
)

print("\nSaved files:")

print(
    "📊",
    DUELING_CSV_PATH
)

print(
    "🧠",
    DUELING_FINAL_MODEL_PATH
)

print(
    "💾",
    DUELING_CHECKPOINT_PATH
)

print("=" * 100)

