import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv


# =====================================================
# Q-value stability diagnostic
# =====================================================

diagnostic_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

# New independent task stream
diagnostic_env.rng = np.random.default_rng(999)

state = diagnostic_env.reset()

states = []

random_rng = np.random.default_rng(999)

for step in range(200):

    states.append(
        state.copy()
    )

    # Random actions only to create a neutral state sample
    action = int(
        random_rng.integers(
            0,
            15
        )
    )

    next_state, reward, done, info = (
        diagnostic_env.step(action)
    )

    state = next_state

    if done:
        break


states = np.asarray(
    states,
    dtype=np.float32
)

print(
    "Diagnostic states:",
    states.shape
)


# =====================================================
# Helper
# =====================================================

def inspect_q_values(
    agent,
    name
):

    x = torch.tensor(
        states,
        dtype=torch.float32,
        device=agent.device
    )

    agent.policy_net.eval()

    with torch.no_grad():

        q = (
            agent.policy_net(x)
            .detach()
            .cpu()
            .numpy()
        )

    return {
        "Model": name,

        "Q_mean":
            float(np.mean(q)),

        "Q_std":
            float(np.std(q)),

        "Q_min":
            float(np.min(q)),

        "Q_max":
            float(np.max(q)),

        "Mean_abs_Q":
            float(np.mean(np.abs(q))),

        "Max_abs_Q":
            float(np.max(np.abs(q))),

        "Mean_action_gap":
            float(
                np.mean(
                    np.sort(q, axis=1)[:, -1]
                    -
                    np.sort(q, axis=1)[:, -2]
                )
            )
    }


q_diagnostic = pd.DataFrame([
    inspect_q_values(
        addqn_eval_agent,
        "ADDQN"
    ),

    inspect_q_values(
        dqn_eval_agent,
        "Vanilla DQN"
    ),

    inspect_q_values(
        ddqn_eval_agent,
        "Vanilla DDQN"
    ),

    inspect_q_values(
        dueling_eval_agent,
        "Dueling DQN"
    )
])


print(
    "\n📊 Q-value magnitude diagnostic"
)

display(
    q_diagnostic.round(4)
)

import numpy as np
import pandas as pd

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv


# =====================================================
# Fixed topology information
# =====================================================

topology_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

capacity = topology_env.capacity_factor.copy()
base_latency = topology_env.base_latency.copy()


# =====================================================
# Action-distribution diagnostic
# =====================================================

def inspect_action_policy(
    agent,
    model_name,
    num_runs=30
):

    counts = np.zeros(
        15,
        dtype=np.int64
    )

    total_rt = []
    total_dmr = []

    for run in range(num_runs):

        task_seed = 100 + run

        env = ImprovedFogSchedulingEnv(
            num_nodes=15,
            max_steps=200,
            seed=42
        )

        # Same task stream protocol
        env.rng = np.random.default_rng(
            task_seed
        )

        state = env.reset()

        for step in range(env.max_steps):

            action = agent.select_action(
                state,
                epsilon=0.0
            )

            counts[action] += 1

            next_state, reward, done, info = (
                env.step(action)
            )

            total_rt.append(
                info["response_time"]
            )

            total_dmr.append(
                info["deadline_miss"]
            )

            state = next_state

            if done:
                break

    # ---------------------------------------------
    # Selection probabilities
    # ---------------------------------------------

    probabilities = (
        counts / counts.sum()
    )

    nonzero_p = probabilities[
        probabilities > 0
    ]

    # Normalized entropy:
    # 1 = distributed across nodes
    # 0 = concentrated on one node
    normalized_entropy = (
        -np.sum(
            nonzero_p
            * np.log(nonzero_p)
        )
        / np.log(15)
    )

    max_share = float(
        probabilities.max()
    )

    dominant_node = int(
        probabilities.argmax()
    )

    active_nodes_1pct = int(
        np.sum(
            probabilities >= 0.01
        )
    )

    weighted_capacity = float(
        np.sum(
            probabilities
            * capacity
        )
    )

    weighted_base_latency = float(
        np.sum(
            probabilities
            * base_latency
        )
    )

    summary = {

        "Model":
            model_name,

        "Total_actions":
            int(counts.sum()),

        "Policy_entropy":
            normalized_entropy,

        "Dominant_node":
            dominant_node,

        "Max_node_share":
            max_share,

        "Nodes_used_>=1%":
            active_nodes_1pct,

        "Selected_capacity_mean":
            weighted_capacity,

        "Selected_base_latency_mean":
            weighted_base_latency,

        "RT_mean":
            float(np.mean(total_rt)),

        "DMR_mean":
            float(np.mean(total_dmr))
    }

    return (
        summary,
        counts,
        probabilities
    )


# =====================================================
# Run diagnostic
# =====================================================

models = [
    (
        addqn_eval_agent,
        "ADDQN"
    ),
    (
        dqn_eval_agent,
        "Vanilla DQN"
    ),
    (
        ddqn_eval_agent,
        "Vanilla DDQN"
    ),
    (
        dueling_eval_agent,
        "Dueling DQN"
    )
]


summaries = []
probabilities_all = {}


for agent, name in models:

    summary, counts, probs = (
        inspect_action_policy(
            agent,
            name
        )
    )

    summaries.append(
        summary
    )

    probabilities_all[name] = probs


policy_summary = pd.DataFrame(
    summaries
)


print(
    "📊 Policy concentration summary"
)

display(
    policy_summary.round(4)
)


# =====================================================
# Node-level table
# =====================================================

node_table = pd.DataFrame({

    "Node":
        np.arange(15),

    "Capacity_factor":
        capacity,

    "Base_latency_ms":
        base_latency,

    "ADDQN_share":
        probabilities_all["ADDQN"],

    "DQN_share":
        probabilities_all["Vanilla DQN"],

    "DDQN_share":
        probabilities_all["Vanilla DDQN"],

    "Dueling_share":
        probabilities_all["Dueling DQN"]
})


print(
    "\n📍 Node-level action distribution"
)

display(
    node_table.round(4)
)


# =====================================================
# Top-5 selected nodes for every policy
# =====================================================

print(
    "\n🏆 Top selected nodes"
)

for name in probabilities_all:

    p = probabilities_all[name]

    top5 = np.argsort(p)[::-1][:5]

    print(
        f"\n{name}:"
    )

    for node in top5:

        print(
            f"Node {node:2d} | "
            f"Share={p[node]*100:6.2f}% | "
            f"Capacity={capacity[node]:.3f} | "
            f"Base latency={base_latency[node]:.2f} ms"
        )

