from DuelingDDQNAgent import DuelingDDQNAgent
import numpy as np

dueling_ddqn_agent = DuelingDDQNAgent(
    state_dim=75,
    action_dim=15,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=True
)

print("✅ Dueling DDQN Agent loaded")
print("Device:", dueling_ddqn_agent.device)

print(
    "Policy parameters:",
    sum(
        p.numel()
        for p in
        dueling_ddqn_agent.policy_net.parameters()
    )
)

test_state = np.zeros(
    75,
    dtype=np.float32
)

action = dueling_ddqn_agent.select_action(
    test_state,
    epsilon=0.0
)

print("Greedy test action:", action)

print(
    "Initial learning rate:",
    dueling_ddqn_agent.get_current_lr()
)

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from DuelingDDQNAgent import DuelingDDQNAgent
import numpy as np

# =====================================================
# Dueling DDQN - 5 episode smoke test
# =====================================================

set_global_seed(42)

dueling_ddqn_test_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

dueling_ddqn_test_agent = DuelingDDQNAgent(
    state_dim=75,
    action_dim=15,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=True
)

episodes = 5

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

batch_size = 64
target_update_freq = 5

print("🧪 Starting Dueling DDQN 5-episode smoke test")
print("=" * 90)

for episode in range(episodes):

    state = dueling_ddqn_test_env.reset()

    total_reward = 0.0
    response_times = []
    deadline_misses = []
    overloads = []
    episode_losses = []

    for step in range(
        dueling_ddqn_test_env.max_steps
    ):

        action = (
            dueling_ddqn_test_agent
            .select_action(
                state,
                epsilon
            )
        )

        next_state, reward, done, info = (
            dueling_ddqn_test_env.step(action)
        )

        dueling_ddqn_test_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )

        loss = dueling_ddqn_test_agent.train(
            batch_size=batch_size
        )

        if loss is not None:
            episode_losses.append(loss)

        state = next_state
        total_reward += reward

        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        if done:
            break

    # Epsilon decay
    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )

    # Target update
    if episode % target_update_freq == 0:
        dueling_ddqn_test_agent.update_target()

    # Scheduler
    dueling_ddqn_test_agent.step_scheduler()

    avg_rt = np.mean(response_times)
    dmr = np.mean(deadline_misses)
    met_ratio = 1.0 - dmr
    overload_ratio = np.mean(overloads)

    avg_loss = (
        np.mean(episode_losses)
        if len(episode_losses) > 0
        else 0.0
    )

    print(
        f"Episode {episode+1:2d} | "
        f"Reward={total_reward:8.2f} | "
        f"RT={avg_rt:7.2f} ms | "
        f"DMR={dmr:.3f} | "
        f"Met={met_ratio:.3f} | "
        f"Overload={overload_ratio:.3f} | "
        f"Loss={avg_loss:8.3f} | "
        f"Epsilon={epsilon:.3f}"
    )

print("=" * 90)
print("✅ Dueling DDQN smoke test completed")

print(
    "Replay buffer:",
    len(
        dueling_ddqn_test_agent.memory
    )
)

print(
    "Training updates:",
    dueling_ddqn_test_agent.training_steps
)

import os
import time
import random
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from DuelingDDQNAgent import DuelingDDQNAgent


# =====================================================
# 1. Reproducibility
# =====================================================

set_global_seed(42)


# =====================================================
# 2. Output paths
# =====================================================

DUELING_DDQN_CSV_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DDQN_training_500episodes.csv"
)

DUELING_DDQN_CHECKPOINT_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DDQN_rolling_checkpoint.pt"
)

DUELING_DDQN_FINAL_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DDQN_final_model.pth"
)


# =====================================================
# 3. Environment
# SAME training protocol
# =====================================================

dueling_ddqn_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

state_dim = len(
    dueling_ddqn_env.reset()
)

action_dim = dueling_ddqn_env.num_nodes


# =====================================================
# 4. Fresh Agent
# =====================================================

dueling_ddqn_agent = DuelingDDQNAgent(
    state_dim=state_dim,
    action_dim=action_dim,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=True
)


# =====================================================
# 5. Training settings
# =====================================================

episodes = 500

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

batch_size = 64
target_update_freq = 5


# =====================================================
# 6. Training log
# =====================================================

dueling_ddqn_training_rows = []

print("🚀 Starting DUELING DDQN training")
print("Episodes:", episodes)
print(
    "Steps per episode:",
    dueling_ddqn_env.max_steps
)

print(
    "Expected interactions:",
    episodes * dueling_ddqn_env.max_steps
)

print(
    "Parameters:",
    sum(
        p.numel()
        for p in
        dueling_ddqn_agent.policy_net.parameters()
    )
)

print(
    "Device:",
    dueling_ddqn_agent.device
)

print("=" * 100)

training_start = time.time()


# =====================================================
# 7. Training loop
# =====================================================

for episode in range(episodes):

    episode_start = time.time()

    state = dueling_ddqn_env.reset()

    total_reward = 0.0

    response_times = []
    deadline_misses = []
    overloads = []

    avg_cpus = []
    avg_queues = []
    avg_energies = []
    chosen_latencies = []

    episode_losses = []


    for step in range(
        dueling_ddqn_env.max_steps
    ):

        # ---------------------------------------------
        # Select action
        # ---------------------------------------------
        action = (
            dueling_ddqn_agent
            .select_action(
                state,
                epsilon
            )
        )

        # ---------------------------------------------
        # Environment step
        # ---------------------------------------------
        next_state, reward, done, info = (
            dueling_ddqn_env.step(action)
        )

        # ---------------------------------------------
        # Replay buffer
        # ---------------------------------------------
        dueling_ddqn_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )

        # ---------------------------------------------
        # Training update
        # ---------------------------------------------
        loss = dueling_ddqn_agent.train(
            batch_size=batch_size
        )

        if loss is not None:
            episode_losses.append(loss)

        state = next_state
        total_reward += reward


        # ---------------------------------------------
        # Metrics
        # ---------------------------------------------
        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        avg_cpus.append(
            info["avg_cpu"]
        )

        avg_queues.append(
            info["avg_queue_ms"]
        )

        avg_energies.append(
            info["avg_energy"]
        )

        chosen_latencies.append(
            info["latency"]
        )

        if done:
            break


    # =================================================
    # End episode
    # =================================================

    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )

    if episode % target_update_freq == 0:
        dueling_ddqn_agent.update_target()

    dueling_ddqn_agent.step_scheduler()


    # =================================================
    # Episode metrics
    # =================================================

    avg_rt = float(
        np.mean(response_times)
    )

    dmr = float(
        np.mean(deadline_misses)
    )

    deadline_met_ratio = float(
        1.0 - dmr
    )

    overload_ratio = float(
        np.mean(overloads)
    )

    episode_avg_loss = (
        float(
            np.mean(
                episode_losses
            )
        )
        if len(episode_losses) > 0
        else 0.0
    )

    stats = (
        dueling_ddqn_agent
        .get_training_stats()
    )

    episode_time = (
        time.time()
        - episode_start
    )


    dueling_ddqn_training_rows.append({

        "episode":
            episode + 1,

        "total_reward":
            float(total_reward),

        "avg_rt":
            avg_rt,

        "dmr":
            dmr,

        "deadline_met_ratio":
            deadline_met_ratio,

        "overload_ratio":
            overload_ratio,

        "epsilon":
            float(epsilon),

        "learning_rate":
            float(
                dueling_ddqn_agent
                .get_current_lr()
            ),

        "avg_cpu":
            float(
                np.mean(avg_cpus)
            ),

        "avg_queue_ms":
            float(
                np.mean(avg_queues)
            ),

        "avg_energy":
            float(
                np.mean(avg_energies)
            ),

        "chosen_latency":
            float(
                np.mean(
                    chosen_latencies
                )
            ),

        "episode_avg_loss":
            episode_avg_loss,

        "avg_loss_last100":
            float(
                stats["avg_loss"]
            ),

        "training_steps":
            int(
                dueling_ddqn_agent
                .training_steps
            ),

        "episode_time_sec":
            float(
                episode_time
            )
    })


    # =================================================
    # Progress every 10 episodes
    # =================================================

    if (
        (episode + 1) % 10 == 0
        or episode == 0
    ):

        print(
            f"Ep {episode+1:3d}/500 | "
            f"R={total_reward:8.1f} | "
            f"RT={avg_rt:7.2f} ms | "
            f"DMR={dmr:.3f} | "
            f"Met={deadline_met_ratio:.3f} | "
            f"ε={epsilon:.3f} | "
            f"Loss={episode_avg_loss:8.2f}"
        )


    # =================================================
    # Save CSV every 10 episodes
    # =================================================

    if (episode + 1) % 10 == 0:

        pd.DataFrame(
            dueling_ddqn_training_rows
        ).to_csv(
            DUELING_DDQN_CSV_PATH,
            index=False
        )


    # =================================================
    # Checkpoint every 25 episodes
    # =================================================

    if (
        (episode + 1) % 25 == 0
        or episode == episodes - 1
    ):

        checkpoint = {

            "episode_index":
                episode,

            "epsilon":
                epsilon,

            "policy_net_state_dict":
                dueling_ddqn_agent
                .policy_net
                .state_dict(),

            "target_net_state_dict":
                dueling_ddqn_agent
                .target_net
                .state_dict(),

            "optimizer_state_dict":
                dueling_ddqn_agent
                .optimizer
                .state_dict(),

            "scheduler_state_dict":
                dueling_ddqn_agent
                .scheduler
                .state_dict(),

            "training_steps":
                dueling_ddqn_agent
                .training_steps,

            "losses":
                dueling_ddqn_agent
                .losses,

            "replay_buffer":
                list(
                    dueling_ddqn_agent
                    .memory
                    .buffer
                ),

            "env_rng_state":
                dueling_ddqn_env
                .rng
                .bit_generator
                .state,

            "python_random_state":
                random.getstate(),

            "numpy_random_state":
                np.random.get_state(),

            "torch_random_state":
                torch.get_rng_state(),

            "cuda_random_state":
                (
                    torch.cuda
                    .get_rng_state_all()
                    if torch.cuda.is_available()
                    else None
                ),

            "training_rows":
                dueling_ddqn_training_rows
        }

        torch.save(
            checkpoint,
            DUELING_DDQN_CHECKPOINT_PATH
        )

        print(
            f"   💾 Dueling DDQN checkpoint "
            f"saved at episode {episode+1}"
        )


# =====================================================
# 8. Save final CSV
# =====================================================

dueling_ddqn_training_df = pd.DataFrame(
    dueling_ddqn_training_rows
)

dueling_ddqn_training_df.to_csv(
    DUELING_DDQN_CSV_PATH,
    index=False
)


# =====================================================
# 9. Save final model
# =====================================================

torch.save(
    {

        "policy_net_state_dict":
            dueling_ddqn_agent
            .policy_net
            .state_dict(),

        "target_net_state_dict":
            dueling_ddqn_agent
            .target_net
            .state_dict(),

        "optimizer_state_dict":
            dueling_ddqn_agent
            .optimizer
            .state_dict(),

        "scheduler_state_dict":
            dueling_ddqn_agent
            .scheduler
            .state_dict(),

        "training_steps":
            dueling_ddqn_agent
            .training_steps,

        "final_epsilon":
            epsilon,

        "state_dim":
            state_dim,

        "action_dim":
            action_dim,

        "hidden_dim":
            256,

        "algorithm":
            "Dueling DDQN"
    },

    DUELING_DDQN_FINAL_MODEL_PATH
)


# =====================================================
# 10. Final summary
# =====================================================

total_training_time = (
    time.time()
    - training_start
)

print("\n" + "=" * 100)

print(
    "✅ DUELING DDQN TRAINING COMPLETE"
)

print(
    f"Total training time: "
    f"{total_training_time/60:.2f} minutes"
)

print(
    f"Final epsilon: "
    f"{epsilon:.4f}"
)

print(
    f"Replay buffer size: "
    f"{len(dueling_ddqn_agent.memory)}"
)

print(
    f"Training updates: "
    f"{dueling_ddqn_agent.training_steps}"
)

print("\nSaved files:")

print(
    "📊",
    DUELING_DDQN_CSV_PATH
)

print(
    "🧠",
    DUELING_DDQN_FINAL_MODEL_PATH
)

print(
    "💾",
    DUELING_DDQN_CHECKPOINT_PATH
)

print("=" * 100)

import os
import torch
import pandas as pd

from DuelingDDQNAgent import DuelingDDQNAgent


# =====================================================
# Load trained Dueling DDQN
# =====================================================

dueling_ddqn_eval_agent = DuelingDDQNAgent(
    state_dim=75,
    action_dim=15,
    lr=3e-4,
    gamma=0.99,
    hidden_dim=256,
    use_lr_scheduler=False
)

dueling_ddqn_ckpt = torch.load(
    DUELING_DDQN_FINAL_MODEL_PATH,
    map_location=dueling_ddqn_eval_agent.device
)

dueling_ddqn_eval_agent.policy_net.load_state_dict(
    dueling_ddqn_ckpt["policy_net_state_dict"]
)

dueling_ddqn_eval_agent.policy_net.eval()

print("✅ Dueling DDQN model loaded")


# =====================================================
# SAME matched evaluation
# topology seed = 42
# task seeds = 100–129
# epsilon = 0
# =====================================================

dueling_ddqn_matched = evaluate_fixed_topology(
    dueling_ddqn_eval_agent,
    "Dueling DDQN"
)


# =====================================================
# Individual summary
# =====================================================

show_summary(
    dueling_ddqn_matched
)


# =====================================================
# Save raw results
# =====================================================

DUELING_DDQN_EVAL_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DDQN_fixed_topology_30runs.csv"
)

dueling_ddqn_matched.to_csv(
    DUELING_DDQN_EVAL_PATH,
    index=False
)


# =====================================================
# Combine principal comparison methods
#
# NOTE:
# Standard Dueling DQN is kept separate because
# its training showed clear instability.
# =====================================================

main_drl_results = pd.concat(
    [
        addqn_matched,
        dqn_matched,
        ddqn_matched,
        dueling_ddqn_matched
    ],
    ignore_index=True
)


MAIN_DRL_PATH = os.path.join(
    SAVE_DIR,
    "Main_DRL_Comparison_ADDQN_DQN_DDQN_DuelingDDQN.csv"
)

main_drl_results.to_csv(
    MAIN_DRL_PATH,
    index=False
)


# =====================================================
# Summary table
# =====================================================

comparison_main = (
    main_drl_results
    .groupby("method")
    .agg(
        RT_mean=("avg_rt", "mean"),
        RT_std=("avg_rt", "std"),

        DMR_mean=("dmr", "mean"),
        DMR_std=("dmr", "std"),

        DeadlineMet_mean=(
            "deadline_met_ratio",
            "mean"
        ),

        Energy_mean=(
            "energy_depletion",
            "mean"
        ),

        LoadImbalance_mean=(
            "load_imbalance",
            "mean"
        ),

        Overload_mean=(
            "overload_ratio",
            "mean"
        )
    )
    .reset_index()
)


# =====================================================
# Rank methods
# Lower is better for RT, DMR, Energy, Load
# =====================================================

comparison_main["RT_rank"] = (
    comparison_main["RT_mean"]
    .rank(method="min")
)

comparison_main["DMR_rank"] = (
    comparison_main["DMR_mean"]
    .rank(method="min")
)

comparison_main["Energy_rank"] = (
    comparison_main["Energy_mean"]
    .rank(method="min")
)

comparison_main["Load_rank"] = (
    comparison_main["LoadImbalance_mean"]
    .rank(method="min")
)


print("\n" + "=" * 115)

print(
    "📊 DEVELOPMENT COMPARISON:"
    " ADDQN vs DQN vs DDQN vs Dueling DDQN"
)

print("=" * 115)

display(
    comparison_main.round(6)
)


print("\n✅ Files saved:")
print(DUELING_DDQN_EVAL_PATH)
print(MAIN_DRL_PATH)

from scipy import stats
import numpy as np
import pandas as pd
import os


# =====================================================
# Vanilla DDQN vs Dueling DDQN
# =====================================================

metrics = {
    "avg_rt": "Response Time (ms)",
    "dmr": "Deadline Miss Ratio",
    "energy_depletion": "Normalized Energy Depletion",
    "load_imbalance": "Load Imbalance"
}

rows = []

for metric, label in metrics.items():

    vanilla = (
        ddqn_matched
        .sort_values("task_seed")[metric]
        .to_numpy()
    )

    dueling = (
        dueling_ddqn_matched
        .sort_values("task_seed")[metric]
        .to_numpy()
    )

    # Vanilla DDQN - Dueling DDQN
    diff = vanilla - dueling

    shapiro_stat, shapiro_p = stats.shapiro(
        diff
    )

    t_stat, t_p = stats.ttest_rel(
        vanilla,
        dueling
    )

    try:
        w_stat, w_p = stats.wilcoxon(
            vanilla,
            dueling,
            alternative="two-sided"
        )
    except ValueError:
        w_stat = np.nan
        w_p = np.nan

    mean_diff = np.mean(diff)

    ci_low, ci_high = stats.t.interval(
        confidence=0.95,
        df=len(diff) - 1,
        loc=mean_diff,
        scale=stats.sem(diff)
    )

    diff_sd = np.std(
        diff,
        ddof=1
    )

    cohens_dz = (
        mean_diff / diff_sd
        if diff_sd > 0
        else np.nan
    )

    # Lower is better
    vanilla_improvement = (
        (
            np.mean(dueling)
            - np.mean(vanilla)
        )
        /
        np.mean(dueling)
        *
        100
    )

    rows.append({

        "Metric":
            label,

        "Vanilla_DDQN_mean":
            np.mean(vanilla),

        "Dueling_DDQN_mean":
            np.mean(dueling),

        "Mean_difference_Vanilla_minus_Dueling":
            mean_diff,

        "CI95_low":
            ci_low,

        "CI95_high":
            ci_high,

        "Shapiro_p":
            shapiro_p,

        "Paired_t":
            t_stat,

        "Paired_t_p":
            t_p,

        "Wilcoxon_W":
            w_stat,

        "Wilcoxon_p":
            w_p,

        "Cohens_dz":
            cohens_dz,

        "Vanilla_DDQN_improvement_percent":
            vanilla_improvement
    })


stats_ddqn_vs_duelingddqn = pd.DataFrame(
    rows
)

pd.set_option(
    "display.max_columns",
    None
)

print(
    "📊 Vanilla DDQN vs Dueling DDQN "
    "— Paired Statistical Analysis"
)

display(
    stats_ddqn_vs_duelingddqn.round(6)
)


# =====================================================
# Save
# =====================================================

PATH = os.path.join(
    SAVE_DIR,
    "stats_Vanilla_DDQN_vs_Dueling_DDQN.csv"
)

stats_ddqn_vs_duelingddqn.to_csv(
    PATH,
    index=False
)

print("\n✅ Saved:")
print(PATH)

