from PPOAgent import PPOAgent
import numpy as np


ppo_agent = PPOAgent(
    state_dim=75,
    action_dim=15,
    lr=3e-4,
    gamma=0.99,
    gae_lambda=0.95,
    clip_eps=0.2,
    ppo_epochs=4,
    minibatch_size=64,
    hidden_dim=256
)

print("✅ PPO Agent loaded")
print("Device:", ppo_agent.device)

print(
    "Parameters:",
    sum(
        p.numel()
        for p in
        ppo_agent.network.parameters()
    )
)

test_state = np.zeros(
    75,
    dtype=np.float32
)

action, log_prob, value = (
    ppo_agent.select_action(
        test_state,
        deterministic=False
    )
)

greedy_action, _, _ = (
    ppo_agent.select_action(
        test_state,
        deterministic=True
    )
)

print("Sampled training action:", action)
print("Deterministic action:", greedy_action)
print("Log probability:", log_prob)
print("State value:", value)
print("Learning rate:", ppo_agent.get_current_lr())
print("Training updates:", ppo_agent.training_updates)

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from PPOAgent import PPOAgent

import numpy as np


# =====================================================
# PPO - 5 episode smoke test
# =====================================================

set_global_seed(42)


# =====================================================
# Environment
# =====================================================

ppo_test_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)


# =====================================================
# Fresh PPO agent
# =====================================================

ppo_test_agent = PPOAgent(
    state_dim=75,
    action_dim=15,

    lr=3e-4,

    gamma=0.99,
    gae_lambda=0.95,

    clip_eps=0.2,

    value_coef=0.5,
    entropy_coef=0.01,

    ppo_epochs=4,
    minibatch_size=64,

    hidden_dim=256,

    max_grad_norm=0.5
)


episodes = 5


print(
    "🧪 Starting PPO 5-episode smoke test"
)

print("=" * 110)


# =====================================================
# Training loop
# =====================================================

for episode in range(episodes):

    state = ppo_test_env.reset()


    # ---------------------------------------------
    # PPO rollout storage
    # ---------------------------------------------

    states = []
    actions = []
    log_probs = []
    values = []

    rewards = []
    dones = []


    # ---------------------------------------------
    # Evaluation metrics
    # ---------------------------------------------

    response_times = []
    deadline_misses = []
    overloads = []


    total_reward = 0.0


    # =============================================
    # Collect one 200-step rollout
    # =============================================

    for step in range(
        ppo_test_env.max_steps
    ):

        action, log_prob, value = (
            ppo_test_agent.select_action(
                state,
                deterministic=False
            )
        )


        next_state, reward, done, info = (
            ppo_test_env.step(action)
        )


        # -----------------------------------------
        # Save PPO transition
        # -----------------------------------------

        states.append(
            state.copy()
        )

        actions.append(
            action
        )

        log_probs.append(
            log_prob
        )

        values.append(
            value
        )

        rewards.append(
            reward
        )

        dones.append(
            float(done)
        )


        # -----------------------------------------
        # Metrics
        # -----------------------------------------

        total_reward += reward

        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )


        state = next_state


        if done:
            break


    # =================================================
    # Bootstrap value
    # =================================================

    if done:

        next_value = 0.0

    else:

        next_value = (
            ppo_test_agent.get_value(
                state
            )
        )


    # =================================================
    # Compute GAE + returns
    # =================================================

    advantages, returns = (
        ppo_test_agent.compute_gae(
            rewards=rewards,
            values=values,
            dones=dones,
            next_value=next_value
        )
    )


    # =================================================
    # PPO update
    # =================================================

    update_stats = (
        ppo_test_agent.update(
            states=states,
            actions=actions,
            old_log_probs=log_probs,
            returns=returns,
            advantages=advantages
        )
    )


    # =================================================
    # Episode metrics
    # =================================================

    avg_rt = float(
        np.mean(response_times)
    )

    dmr = float(
        np.mean(deadline_misses)
    )

    met_ratio = (
        1.0 - dmr
    )

    overload_ratio = float(
        np.mean(overloads)
    )


    print(
        f"Episode {episode+1:2d} | "
        f"Reward={total_reward:8.2f} | "
        f"RT={avg_rt:7.2f} ms | "
        f"DMR={dmr:.3f} | "
        f"Met={met_ratio:.3f} | "
        f"Overload={overload_ratio:.3f} | "
        f"Loss={update_stats['loss']:10.2f} | "
        f"Actor={update_stats['actor_loss']:8.4f} | "
        f"Critic={update_stats['critic_loss']:10.2f} | "
        f"Entropy={update_stats['entropy']:.4f} | "
        f"Clip={update_stats['clip_fraction']:.3f}"
    )


print("=" * 110)

print(
    "✅ PPO smoke test completed"
)

print(
    "Training updates:",
    ppo_test_agent.training_updates
)

