PPO_FINAL_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "PPO_final_model.pth"
)


# =====================================================
# 3. Environment
# Same 15-node training topology
# =====================================================

ppo_env = ImprovedFogSchedulingEnv(
    num_nodes=15,
    max_steps=200,
    seed=42
)

state_dim = len(
    ppo_env.reset()
)

action_dim = ppo_env.num_nodes


# =====================================================
# 4. Fresh PPO Agent
# =====================================================

ppo_agent = PPOAgent(
    state_dim=state_dim,
    action_dim=action_dim,

    lr=3e-4,

    gamma=0.99,
    gae_lambda=0.95,

    clip_eps=0.2,

    value_coef=0.5,
    entropy_coef=0.01,

    ppo_epochs=4,
    minibatch_size=64,

    hidden_dim=256,

    max_grad_norm=0.5
)


# =====================================================
# 5. Training configuration
# =====================================================

episodes = 500

ppo_training_rows = []

print("🚀 Starting PPO training")
print("Episodes:", episodes)
print("Steps per episode:", ppo_env.max_steps)

print(
    "Expected environment interactions:",
    episodes * ppo_env.max_steps
)

print(
    "Parameters:",
    sum(
        p.numel()
        for p in ppo_agent.network.parameters()
    )
)

print(
    "Device:",
    ppo_agent.device
)

print("=" * 110)

training_start = time.time()


# =====================================================
# 6. Training Loop
# =====================================================

for episode in range(episodes):

    episode_start = time.time()

    state = ppo_env.reset()


    # -------------------------------------------------
    # PPO rollout storage
    # -------------------------------------------------

    states = []
    actions = []
    log_probs = []
    values = []

    rewards = []
    dones = []


    # -------------------------------------------------
    # Performance metrics
    # -------------------------------------------------

    response_times = []
    deadline_misses = []
    overloads = []

    avg_cpus = []
    avg_queues = []
    avg_energies = []
    chosen_latencies = []

    queue_imbalances = []

    total_reward = 0.0


    # =================================================
    # Collect one episode rollout
    # =================================================

    for step in range(
        ppo_env.max_steps
    ):

        action, log_prob, value = (
            ppo_agent.select_action(
                state,
                deterministic=False
            )
        )

        next_state, reward, done, info = (
            ppo_env.step(action)
        )


        # ---------------------------------------------
        # Store rollout
        # ---------------------------------------------

        states.append(
            state.copy()
        )

        actions.append(
            action
        )

        log_probs.append(
            log_prob
        )

        values.append(
            value
        )

        rewards.append(
            reward
        )

        dones.append(
            float(done)
        )


        # ---------------------------------------------
        # Metrics
        # ---------------------------------------------

        total_reward += reward

        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        avg_cpus.append(
            info["avg_cpu"]
        )

        avg_queues.append(
            info["avg_queue_ms"]
        )

        avg_energies.append(
            info["avg_energy"]
        )

        chosen_latencies.append(
            info["latency"]
        )

        queue_imbalances.append(
            np.std(
                ppo_env.queue_ms
            )
            / ppo_env.queue_cap_ms
        )


        state = next_state


        if done:
            break


    # =================================================
    # Bootstrap
    # =================================================

    if done:

        next_value = 0.0

    else:

        next_value = (
            ppo_agent.get_value(
                state
            )
        )


    # =================================================
    # GAE + Returns
    # =================================================

    advantages, returns = (
        ppo_agent.compute_gae(
            rewards=rewards,
            values=values,
            dones=dones,
            next_value=next_value
        )
    )


    # =================================================
    # PPO Update
    # =================================================

    update_stats = (
        ppo_agent.update(
            states=states,
            actions=actions,
            old_log_probs=log_probs,
            returns=returns,
            advantages=advantages
        )
    )


    # =================================================
    # Episode statistics
    # =================================================

    avg_rt = float(
        np.mean(response_times)
    )

    dmr = float(
        np.mean(deadline_misses)
    )

    deadline_met_ratio = float(
        1.0 - dmr
    )

    overload_ratio = float(
        np.mean(overloads)
    )

    energy_depletion = float(
        np.sum(
            1.0 - ppo_env.energy
        )
    )

    load_imbalance = float(
        np.mean(
            queue_imbalances
        )
    )

    episode_time = (
        time.time()
        - episode_start
    )


    ppo_training_rows.append({

        "episode":
            episode + 1,

        "total_reward":
            float(total_reward),

        "avg_rt":
            avg_rt,

        "dmr":
            dmr,

        "deadline_met_ratio":
            deadline_met_ratio,

        "overload_ratio":
            overload_ratio,

        "energy_depletion":
            energy_depletion,

        "load_imbalance":
            load_imbalance,

        "avg_cpu":
            float(
                np.mean(avg_cpus)
            ),

        "avg_queue_ms":
            float(
                np.mean(avg_queues)
            ),

        "avg_energy":
            float(
                np.mean(avg_energies)
            ),

        "chosen_latency":
            float(
                np.mean(chosen_latencies)
            ),

        # PPO-specific diagnostics
        "ppo_loss":
            update_stats["loss"],

        "actor_loss":
            update_stats["actor_loss"],

        "critic_loss":
            update_stats["critic_loss"],

        "entropy":
            update_stats["entropy"],

        "clip_fraction":
            update_stats["clip_fraction"],

        "learning_rate":
            ppo_agent.get_current_lr(),

        "training_updates":
            ppo_agent.training_updates,

        "episode_time_sec":
            float(episode_time)
    })


    # =================================================
    # Progress every 10 episodes
    # =================================================

    if (
        (episode + 1) % 10 == 0
        or episode == 0
    ):

        print(
            f"Ep {episode+1:3d}/500 | "
            f"R={total_reward:8.1f} | "
            f"RT={avg_rt:7.2f} | "
            f"DMR={dmr:.3f} | "
            f"Met={deadline_met_ratio:.3f} | "
            f"Entropy={update_stats['entropy']:.3f} | "
            f"Clip={update_stats['clip_fraction']:.3f} | "
            f"Critic={update_stats['critic_loss']:10.1f}"
        )


    # =================================================
    # Save CSV every 10 episodes
    # =================================================

    if (episode + 1) % 10 == 0:

        pd.DataFrame(
            ppo_training_rows
        ).to_csv(
            PPO_CSV_PATH,
            index=False
        )


    # =================================================
    # Checkpoint every 25 episodes
    # =================================================

    if (
        (episode + 1) % 25 == 0
        or episode == episodes - 1
    ):

        checkpoint = {

            "episode_index":
                episode,

            "network_state_dict":
                ppo_agent.network.state_dict(),

            "optimizer_state_dict":
                ppo_agent.optimizer.state_dict(),

            "training_updates":
                ppo_agent.training_updates,

            "loss_history":
                ppo_agent.loss_history,

            "python_random_state":
                random.getstate(),

            "numpy_random_state":
                np.random.get_state(),

            "torch_random_state":
                torch.get_rng_state(),

            "cuda_random_state":
                (
                    torch.cuda.get_rng_state_all()
                    if torch.cuda.is_available()
                    else None
                ),

            "env_rng_state":
                ppo_env.rng.bit_generator.state,

            "training_rows":
                ppo_training_rows
        }

        torch.save(
            checkpoint,
            PPO_CHECKPOINT_PATH
        )

        print(
            f"   💾 PPO checkpoint saved "
            f"at episode {episode+1}"
        )


# =====================================================
# 7. Save final training CSV
# =====================================================

ppo_training_df = pd.DataFrame(
    ppo_training_rows
)

ppo_training_df.to_csv(
    PPO_CSV_PATH,
    index=False
)


# =====================================================
# 8. Save final PPO model
# =====================================================

torch.save(
    {

        "network_state_dict":
            ppo_agent.network.state_dict(),

        "optimizer_state_dict":
            ppo_agent.optimizer.state_dict(),

        "training_updates":
            ppo_agent.training_updates,

        "state_dim":
            state_dim,

        "action_dim":
            action_dim,

        "hidden_dim":
            256,

        "lr":
            3e-4,

        "gamma":
            0.99,

        "gae_lambda":
            0.95,

        "clip_eps":
            0.2,

        "entropy_coef":
            0.01,

        "value_coef":
            0.5,

        "ppo_epochs":
            4,

        "minibatch_size":
            64,

        "algorithm":
            "PPO"
    },

    PPO_FINAL_MODEL_PATH
)


# =====================================================
# 9. Final Summary
# =====================================================

total_training_time = (
    time.time()
    - training_start
)

print("\n" + "=" * 110)

print(
    "✅ PPO TRAINING COMPLETE"
)

print(
    f"Total training time: "
    f"{total_training_time/60:.2f} minutes"
)

print(
    "Environment interactions:",
    episodes * ppo_env.max_steps
)

print(
    "PPO minibatch updates:",
    ppo_agent.training_updates
)

print(
    f"Final entropy: "
    f"{ppo_training_rows[-1]['entropy']:.4f}"
)

print(
    f"Final clip fraction: "
    f"{ppo_training_rows[-1]['clip_fraction']:.4f}"
)

print("\nSaved files:")

print(
    "📊",
    PPO_CSV_PATH
)

print(
    "🧠",
    PPO_FINAL_MODEL_PATH
)

print(
    "💾",
    PPO_CHECKPOINT_PATH
)

print("=" * 110)

import pandas as pd
