import os
import random
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from PPOAgent import PPOAgent


# =====================================================
# FINAL PPO DEVELOPMENT EVALUATION
#
# Same fixed topology: seed = 42
# Same task seeds: 100–129
#
# PPO stochastic policy:
# 5 controlled policy-sampling replicates per task seed
#
# Final statistical unit = task seed
# N = 30
# =====================================================

PPO_DEV_TASK_SEEDS = list(
    range(100, 130)
)

PPO_POLICY_SEEDS = [
    6001,
    6002,
    6003,
    6004,
    6005
]


# =====================================================
# Controlled action-sampling seed
# =====================================================

def set_ppo_sampling_seed(seed):

    random.seed(seed)

    np.random.seed(seed)

    torch.manual_seed(seed)

    if torch.cuda.is_available():

        torch.cuda.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)


# =====================================================
# Load FINAL stabilized PPO
# =====================================================

ppo_dev_agent = PPOAgent(
    state_dim=75,
    action_dim=15,

    lr=3e-4,

    gamma=0.99,
    gae_lambda=0.95,

    clip_eps=0.2,

    value_coef=0.5,
    entropy_coef=0.01,

    ppo_epochs=4,
    minibatch_size=64,

    hidden_dim=256,
    max_grad_norm=0.5
)


ppo_checkpoint = torch.load(
    PPO_SCALED_FINAL_MODEL_PATH,
    map_location=ppo_dev_agent.device
)

ppo_dev_agent.network.load_state_dict(
    ppo_checkpoint[
        "network_state_dict"
    ]
)

ppo_dev_agent.network.eval()


print("✅ Final stabilized PPO loaded")

print(
    "Parameters:",
    sum(
        p.numel()
        for p in
        ppo_dev_agent.network.parameters()
    )
)


# =====================================================
# Evaluation
# =====================================================

raw_rows = []

overall_action_counts = np.zeros(
    15,
    dtype=np.int64
)


for task_seed in PPO_DEV_TASK_SEEDS:

    for policy_seed in PPO_POLICY_SEEDS:

        # -----------------------------------------
        # Fixed topology
        # -----------------------------------------

        env = ImprovedFogSchedulingEnv(
            num_nodes=15,
            max_steps=200,
            seed=42
        )

        # -----------------------------------------
        # Same task stream used for this seed
        # -----------------------------------------

        env.rng = np.random.default_rng(
            task_seed
        )

        # -----------------------------------------
        # Controlled stochastic PPO policy
        # -----------------------------------------

        set_ppo_sampling_seed(
            policy_seed
        )

        state = env.reset()


        rewards = []
        response_times = []
        deadline_misses = []
        overloads = []
        queue_imbalances = []

        run_action_counts = np.zeros(
            15,
            dtype=np.int64
        )


        # =========================================
        # 200 scheduling decisions
        # =========================================

        for step in range(
            env.max_steps
        ):

            action, _, _ = (
                ppo_dev_agent.select_action(
                    state,
                    deterministic=False
                )
            )

            run_action_counts[
                action
            ] += 1

            overall_action_counts[
                action
            ] += 1


            next_state, reward, done, info = (
                env.step(action)
            )


            rewards.append(
                reward
            )

            response_times.append(
                info["response_time"]
            )

            deadline_misses.append(
                info["deadline_miss"]
            )

            overloads.append(
                info["overload"]
            )

            queue_imbalances.append(
                np.std(
                    env.queue_ms
                )
                / env.queue_cap_ms
            )


            state = next_state


            if done:
                break


        # =========================================
        # Per-run action entropy
        # =========================================

        probs = (
            run_action_counts
            / run_action_counts.sum()
        )

        nonzero = probs[
            probs > 0
        ]

        action_entropy = float(
            -np.sum(
                nonzero
                * np.log(nonzero)
            )
            / np.log(15)
        )


        dmr = float(
            np.mean(
                deadline_misses
            )
        )


        raw_rows.append({

            "task_seed":
                task_seed,

            "policy_seed":
                policy_seed,

            "avg_reward":
                float(
                    np.mean(rewards)
                ),

            "avg_rt":
                float(
                    np.mean(
                        response_times
                    )
                ),

            "dmr":
                dmr,

            "deadline_met_ratio":
                1.0 - dmr,

            "energy_depletion":
                float(
                    np.sum(
                        1.0 - env.energy
                    )
                ),

            "load_imbalance":
                float(
                    np.mean(
                        queue_imbalances
                    )
                ),

            "overload_ratio":
                float(
                    np.mean(
                        overloads
                    )
                ),

            "action_entropy":
                action_entropy,

            "dominant_node_share":
                float(
                    probs.max()
                )
        })


# =====================================================
# Raw 150 stochastic runs
# =====================================================

ppo_dev_raw = pd.DataFrame(
    raw_rows
)


# =====================================================
# IMPORTANT:
# Collapse 5 PPO replicates into ONE result per task seed
#
# Final N remains 30
# =====================================================

ppo_dev_matched = (
    ppo_dev_raw
    .groupby(
        "task_seed",
        as_index=False
    )
    .agg(

        avg_reward=(
            "avg_reward",
            "mean"
        ),

        avg_rt=(
            "avg_rt",
            "mean"
        ),

        dmr=(
            "dmr",
            "mean"
        ),

        deadline_met_ratio=(
            "deadline_met_ratio",
            "mean"
        ),

        energy_depletion=(
            "energy_depletion",
            "mean"
        ),

        load_imbalance=(
            "load_imbalance",
            "mean"
        ),

        overload_ratio=(
            "overload_ratio",
            "mean"
        ),

        action_entropy=(
            "action_entropy",
            "mean"
        ),

        dominant_node_share=(
            "dominant_node_share",
            "mean"
        )
    )
)


# =====================================================
# Overall scheduling distribution
# =====================================================

overall_probs = (
    overall_action_counts
    / overall_action_counts.sum()
)

nz = overall_probs[
    overall_probs > 0
]

overall_entropy = float(
    -np.sum(
        nz * np.log(nz)
    )
    / np.log(15)
)

dominant_node = int(
    np.argmax(
        overall_probs
    )
)

dominant_share = float(
    overall_probs[
        dominant_node
    ]
)


# =====================================================
# Summary
# =====================================================

print("\n" + "=" * 75)

print(
    "FINAL PPO DEVELOPMENT EVALUATION"
)

print("=" * 75)

print(
    f"RT: "
    f"{ppo_dev_matched['avg_rt'].mean():.2f} "
    f"± "
    f"{ppo_dev_matched['avg_rt'].std(ddof=1):.2f} ms"
)

print(
    f"DMR: "
    f"{ppo_dev_matched['dmr'].mean():.4f} "
    f"± "
    f"{ppo_dev_matched['dmr'].std(ddof=1):.4f}"
)

print(
    f"Deadline Met: "
    f"{ppo_dev_matched['deadline_met_ratio'].mean()*100:.2f}% "
    f"± "
    f"{ppo_dev_matched['deadline_met_ratio'].std(ddof=1)*100:.2f}%"
)

print(
    f"Energy depletion: "
    f"{ppo_dev_matched['energy_depletion'].mean():.6f} "
    f"± "
    f"{ppo_dev_matched['energy_depletion'].std(ddof=1):.6f}"
)

print(
    f"Load imbalance: "
    f"{ppo_dev_matched['load_imbalance'].mean():.6f} "
    f"± "
    f"{ppo_dev_matched['load_imbalance'].std(ddof=1):.6f}"
)

print(
    f"Overload ratio: "
    f"{ppo_dev_matched['overload_ratio'].mean():.4f}"
)

print(
    f"Action entropy: "
    f"{ppo_dev_matched['action_entropy'].mean():.4f}"
)

print(
    f"Overall action entropy: "
    f"{overall_entropy:.4f}"
)

print(
    f"Dominant node: "
    f"{dominant_node}"
)

print(
    f"Dominant node share: "
    f"{dominant_share*100:.2f}%"
)

print(
    "Raw PPO runs:",
    len(ppo_dev_raw)
)

print(
    "Matched statistical units:",
    len(ppo_dev_matched)
)


# =====================================================
# Save
# =====================================================

PPO_DEV_RAW_PATH = os.path.join(
    SAVE_DIR,
    "PPO_final_development_150rawruns.csv"
)

PPO_DEV_MATCHED_PATH = os.path.join(
    SAVE_DIR,
    "PPO_final_development_30matched.csv"
)


ppo_dev_raw.to_csv(
    PPO_DEV_RAW_PATH,
    index=False
)

ppo_dev_matched.to_csv(
    PPO_DEV_MATCHED_PATH,
    index=False
)


print("\n✅ Saved:")
print(PPO_DEV_RAW_PATH)
print(PPO_DEV_MATCHED_PATH)

import os
import pandas as pd


# =====================================================
# Build one unified DEVELOPMENT comparison table
# =====================================================

development_methods = {
    "ADDQN":
        addqn_matched,

    "Vanilla DQN":
        dqn_matched,

    "Vanilla DDQN":
        ddqn_matched,

    "Dueling DDQN":
        dueling_ddqn_matched,

    "PPO":
        ppo_dev_matched
}


rows = []


for method, df in development_methods.items():

    row = {

        "Method":
            method,

        "N_task_seeds":
            len(df),

        "RT_mean_ms":
            df["avg_rt"].mean(),

        "RT_std_ms":
            df["avg_rt"].std(ddof=1),

        "DMR_mean":
            df["dmr"].mean(),

        "DMR_std":
            df["dmr"].std(ddof=1),

        "DeadlineMet_mean":
            df[
                "deadline_met_ratio"
            ].mean(),

        "DeadlineMet_std":
            df[
                "deadline_met_ratio"
            ].std(ddof=1),

        "Energy_mean":
            df[
                "energy_depletion"
            ].mean(),

        "Energy_std":
            df[
                "energy_depletion"
            ].std(ddof=1),

        "LoadImbalance_mean":
            df[
                "load_imbalance"
            ].mean(),

        "LoadImbalance_std":
            df[
                "load_imbalance"
            ].std(ddof=1),

        "Overload_mean":
            df[
                "overload_ratio"
            ].mean()
    }

    # Add reward if available
    if "avg_reward" in df.columns:

        row["Reward_mean"] = (
            df["avg_reward"].mean()
        )

        row["Reward_std"] = (
            df["avg_reward"].std(ddof=1)
        )

    else:

        row["Reward_mean"] = None
        row["Reward_std"] = None


    rows.append(row)


development_summary = pd.DataFrame(
    rows
)


# =====================================================
# Rankings
# Lower is better except deadline-met and reward
# =====================================================

development_summary["RT_rank"] = (
    development_summary[
        "RT_mean_ms"
    ]
    .rank(
        method="min",
        ascending=True
    )
)

development_summary["DMR_rank"] = (
    development_summary[
        "DMR_mean"
    ]
    .rank(
        method="min",
        ascending=True
    )
)

development_summary["Energy_rank"] = (
    development_summary[
        "Energy_mean"
    ]
    .rank(
        method="min",
        ascending=True
    )
)

development_summary["Load_rank"] = (
    development_summary[
        "LoadImbalance_mean"
    ]
    .rank(
        method="min",
        ascending=True
    )
)


# =====================================================
# Sort by DMR first
# =====================================================

development_summary = (
    development_summary
    .sort_values(
        [
            "DMR_rank",
            "RT_rank"
        ]
    )
    .reset_index(drop=True)
)


print(
    "\n"
    + "=" * 125
)

print(
    "📊 COMPLETE DRL DEVELOPMENT COMPARISON"
)

print(
    "Fixed topology seed = 42 | "
    "Task seeds = 100–129 | "
    "N = 30"
)

print(
    "=" * 125
)


display(
    development_summary.round(6)
)


# =====================================================
# Save
# =====================================================

DEVELOPMENT_SUMMARY_PATH = os.path.join(
    SAVE_DIR,
    "Complete_DRL_Development_Comparison.csv"
)

development_summary.to_csv(
    DEVELOPMENT_SUMMARY_PATH,
    index=False
)


