import os
import numpy as np
import pandas as pd
from scipy import stats


# =====================================================
# ADDQN vs Vanilla DDQN
# PAIRED UNSEEN-TOPOLOGY ANALYSIS
# =====================================================


# -----------------------------------------------------
# Merge exact same topology/task pairs
# -----------------------------------------------------

paired_unseen = pd.merge(

    addqn_unseen_topology,

    ddqn_unseen_topology,

    on=[
        "topology_seed",
        "task_seed"
    ],

    suffixes=(
        "_ADDQN",
        "_DDQN"
    )
)


assert len(paired_unseen) == 30


print(
    "✅ Matched unseen topologies:",
    len(paired_unseen)
)


# =====================================================
# Statistical comparison
# =====================================================

metrics = {

    "avg_rt":
        "Response Time (ms)",

    "dmr":
        "Deadline Miss Ratio",

    "energy_depletion":
        "Normalized Energy Depletion",

    "load_imbalance":
        "Load Imbalance"
}


stat_rows = []


for metric, label in metrics.items():

    addqn = paired_unseen[
        f"{metric}_ADDQN"
    ].to_numpy()

    ddqn = paired_unseen[
        f"{metric}_DDQN"
    ].to_numpy()


    # ADDQN - DDQN
    diff = addqn - ddqn


    # ---------------------------------------------
    # Normality of paired differences
    # ---------------------------------------------

    shapiro_stat, shapiro_p = (
        stats.shapiro(
            diff
        )
    )


    # ---------------------------------------------
    # Paired t-test
    # ---------------------------------------------

    t_stat, t_p = stats.ttest_rel(
        addqn,
        ddqn
    )


    # ---------------------------------------------
    # Wilcoxon
    # ---------------------------------------------

    try:

        w_stat, w_p = stats.wilcoxon(
            addqn,
            ddqn,
            alternative="two-sided"
        )

    except ValueError:

        w_stat = np.nan
        w_p = np.nan


    # ---------------------------------------------
    # 95% CI of paired mean difference
    # ---------------------------------------------

    mean_diff = float(
        np.mean(diff)
    )

    sem_diff = stats.sem(
        diff
    )

    ci_low, ci_high = stats.t.interval(

        confidence=0.95,

        df=len(diff) - 1,

        loc=mean_diff,

        scale=sem_diff
    )


    # ---------------------------------------------
    # Cohen's dz
    # ---------------------------------------------

    diff_sd = np.std(
        diff,
        ddof=1
    )

    cohens_dz = (

        mean_diff / diff_sd

        if diff_sd > 0

        else np.nan
    )


    # ---------------------------------------------
    # Relative improvement
    # Lower is better
    # ---------------------------------------------

    relative_improvement = (

        (
            np.mean(ddqn)
            - np.mean(addqn)
        )

        / np.mean(ddqn)

        * 100
    )


    stat_rows.append({

        "Metric":
            label,

        "ADDQN_mean":
            np.mean(addqn),

        "DDQN_mean":
            np.mean(ddqn),

        "ADDQN_minus_DDQN":
            mean_diff,

        "CI95_low":
            ci_low,

        "CI95_high":
            ci_high,

        "Shapiro_p":
            shapiro_p,

        "Paired_t":
            t_stat,

        "Paired_t_p":
            t_p,

        "Wilcoxon_W":
            w_stat,

        "Wilcoxon_p":
            w_p,

        "Cohens_dz":
            cohens_dz,

        "ADDQN_relative_improvement_percent":
            relative_improvement
    })


unseen_stats = pd.DataFrame(
    stat_rows
)


print(
    "\n"
    + "=" * 120
)

print(
    "📊 ADDQN vs VANILLA DDQN "
    "ON 30 UNSEEN TOPOLOGIES"
)

print(
    "=" * 120
)


display(
    unseen_stats.round(6)
)


# =====================================================
# GENERALIZATION GAP
# Fixed topology -> unseen topology
# =====================================================


fixed_addqn = {

    "RT":
        addqn_matched[
            "avg_rt"
        ].mean(),

    "DMR":
        addqn_matched[
            "dmr"
        ].mean()
}


fixed_ddqn = {

    "RT":
        ddqn_matched[
            "avg_rt"
        ].mean(),

    "DMR":
        ddqn_matched[
            "dmr"
        ].mean()
}


unseen_addqn = {

    "RT":
        addqn_unseen_topology[
            "avg_rt"
        ].mean(),

    "DMR":
        addqn_unseen_topology[
            "dmr"
        ].mean()
}


unseen_ddqn = {

    "RT":
        ddqn_unseen_topology[
            "avg_rt"
        ].mean(),

    "DMR":
        ddqn_unseen_topology[
            "dmr"
        ].mean()
}


gap_rows = []


for method, fixed, unseen in [

    (
        "ADDQN",
        fixed_addqn,
        unseen_addqn
    ),

    (
        "Vanilla DDQN",
        fixed_ddqn,
        unseen_ddqn
    )
]:

    rt_abs = (
        unseen["RT"]
        - fixed["RT"]
    )

    rt_pct = (
        rt_abs
        / fixed["RT"]
        * 100
    )


    dmr_abs = (
        unseen["DMR"]
        - fixed["DMR"]
    )

    dmr_relative = (
        dmr_abs
        / fixed["DMR"]
        * 100
    )


    gap_rows.append({

        "Method":
            method,

        "Fixed_RT":
            fixed["RT"],

        "Unseen_RT":
            unseen["RT"],

        "RT_absolute_degradation_ms":
            rt_abs,

        "RT_relative_degradation_percent":
            rt_pct,

        "Fixed_DMR":
            fixed["DMR"],

        "Unseen_DMR":
            unseen["DMR"],

        "DMR_absolute_increase":
            dmr_abs,

        "DMR_relative_increase_percent":
            dmr_relative
    })


generalization_gap = pd.DataFrame(
    gap_rows
)


print(
    "\n"
    + "=" * 120
)

print(
    "🌐 GENERALIZATION GAP: "
    "TRAINING TOPOLOGY → UNSEEN TOPOLOGIES"
)

print(
    "=" * 120
)


display(
    generalization_gap.round(6)
)


# =====================================================
# Save
# =====================================================

UNSEEN_STATS_PATH = os.path.join(

    SAVE_DIR,

    "stats_ADDQN_vs_DDQN_unseen_topologies.csv"
)


GENERALIZATION_GAP_PATH = os.path.join(

    SAVE_DIR,

    "generalization_gap_ADDQN_vs_DDQN.csv"
)


PAIRED_UNSEEN_PATH = os.path.join(

    SAVE_DIR,

    "paired_ADDQN_DDQN_unseen_topologies.csv"
)


unseen_stats.to_csv(
    UNSEEN_STATS_PATH,
    index=False
)

generalization_gap.to_csv(
    GENERALIZATION_GAP_PATH,
    index=False
)

paired_unseen.to_csv(
    PAIRED_UNSEEN_PATH,
    index=False
)


print(
    "\n✅ Saved:"
)

