import os
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv


# =====================================================
# Generic deterministic unseen-topology evaluator
# For DQN-family agents
# =====================================================

def evaluate_unseen_value_agent(
    agent,
    method_name,
    topology_seeds=range(1000, 1030),
    task_seeds=range(5000, 5030)
):

    rows = []

    for idx, (topology_seed, task_seed) in enumerate(
        zip(topology_seeds, task_seeds)
    ):

        env = ImprovedFogSchedulingEnv(
            num_nodes=15,
            max_steps=200,
            seed=topology_seed
        )

        # Topology fingerprint
        capacity_mean = float(
            np.mean(env.capacity_factor)
        )

        capacity_std = float(
            np.std(env.capacity_factor)
        )

        latency_mean = float(
            np.mean(env.base_latency)
        )

        latency_std = float(
            np.std(env.base_latency)
        )

        fastest_node = int(
            np.argmin(env.base_latency)
        )

        highest_capacity_node = int(
            np.argmax(env.capacity_factor)
        )

        # Same controlled task stream
        env.rng = np.random.default_rng(
            task_seed
        )

        state = env.reset()

        rewards = []
        rts = []
        misses = []
        overloads = []
        queue_imbalances = []

        action_counts = np.zeros(
            15,
            dtype=np.int64
        )

        for step in range(
            env.max_steps
        ):

            action = agent.select_action(
                state,
                epsilon=0.0
            )

            action_counts[action] += 1

            next_state, reward, done, info = (
                env.step(action)
            )

            rewards.append(reward)

            rts.append(
                info["response_time"]
            )

            misses.append(
                info["deadline_miss"]
            )

            overloads.append(
                info["overload"]
            )

            queue_imbalances.append(
                np.std(env.queue_ms)
                / env.queue_cap_ms
            )

            state = next_state

            if done:
                break

        probs = (
            action_counts
            / action_counts.sum()
        )

        nz = probs[
            probs > 0
        ]

        action_entropy = float(
            -np.sum(
                nz * np.log(nz)
            )
            / np.log(15)
        )

        dmr = float(
            np.mean(misses)
        )

        rows.append({

            "method":
                method_name,

            "topology_index":
                idx,

            "topology_seed":
                topology_seed,

            "task_seed":
                task_seed,

            "avg_rt":
                float(
                    np.mean(rts)
                ),

            "dmr":
                dmr,

            "deadline_met_ratio":
                1.0 - dmr,

            "avg_reward":
                float(
                    np.mean(rewards)
                ),

            "energy_depletion":
                float(
                    np.sum(
                        1.0 - env.energy
                    )
                ),

            "load_imbalance":
                float(
                    np.mean(
                        queue_imbalances
                    )
                ),

            "overload_ratio":
                float(
                    np.mean(overloads)
                ),

            "action_entropy":
                action_entropy,

            "dominant_node":
                int(
                    np.argmax(probs)
                ),

            "dominant_node_share":
                float(
                    probs.max()
                ),

            "active_nodes":
                int(
                    np.sum(
                        action_counts > 0
                    )
                ),

            "capacity_mean":
                capacity_mean,

            "capacity_std":
                capacity_std,

            "base_latency_mean":
                latency_mean,

            "base_latency_std":
                latency_std,

            "fastest_node":
                fastest_node,

            "highest_capacity_node":
                highest_capacity_node
        })

    return pd.DataFrame(rows)


