import numpy as np

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from ImprovedDQNAgent import ImprovedDQNAgent


# =====================================================
# ADDQN 50-NODE SMOKE TEST
# Corrected for original ImprovedDQNAgent API
# =====================================================

NUM_NODES_50 = 50
STATE_DIM_50 = NUM_NODES_50 * 5
ACTION_DIM_50 = NUM_NODES_50

DT_50 = 15 / 50       # 0.30

MAX_STEPS = 200
SMOKE_EPISODES = 5


# =====================================================
# Reproducibility
# =====================================================

set_global_seed(42)


# =====================================================
# Environment
# =====================================================

env_50_test = ImprovedFogSchedulingEnv(
    num_nodes=NUM_NODES_50,
    max_steps=MAX_STEPS,
    seed=42,
    dt=DT_50
)


# =====================================================
# Fresh ADDQN Agent
# =====================================================

addqn_50_test_agent = ImprovedDQNAgent(
    state_dim=STATE_DIM_50,
    action_dim=ACTION_DIM_50,
    num_nodes=NUM_NODES_50,

    lr=3e-4,
    gamma=0.99,

    hidden_dim=128
)


print("=" * 105)
print("🧪 ADDQN 50-node smoke test")

print("Nodes:", NUM_NODES_50)
print("State dim:", STATE_DIM_50)
print("Actions:", ACTION_DIM_50)
print("dt:", DT_50)

print(
    "Parameters:",
    sum(
        p.numel()
        for p in
        addqn_50_test_agent.policy_net.parameters()
    )
)

print("=" * 105)


# =====================================================
# Smoke training
# =====================================================

epsilon = 1.0


for episode in range(
    SMOKE_EPISODES
):

    state = env_50_test.reset()

    total_reward = 0.0

    response_times = []
    deadline_misses = []
    overloads = []

    losses = []


    for step in range(
        MAX_STEPS
    ):

        # ---------------------------------------------
        # Select action
        # ---------------------------------------------

        action = (
            addqn_50_test_agent.select_action(
                state,
                epsilon
            )
        )


        # ---------------------------------------------
        # Environment step
        # ---------------------------------------------

        next_state, reward, done, info = (
            env_50_test.step(
                action
            )
        )


        # ---------------------------------------------
        # ORIGINAL replay-buffer API
        # ---------------------------------------------

        addqn_50_test_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )


        # ---------------------------------------------
        # ORIGINAL training method
        # ---------------------------------------------

        loss = (
            addqn_50_test_agent.train(
                batch_size=64
            )
        )


        if loss is not None:

            losses.append(
                loss
            )


        # ---------------------------------------------
        # Metrics
        # ---------------------------------------------

        total_reward += reward

        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )


        state = next_state


        if done:
            break


    # =================================================
    # Same original target-network convention
    # episode index = 0,5,10,...
    # =================================================

    if episode % 5 == 0:

        addqn_50_test_agent.update_target()


    # =================================================
    # Same LR scheduler protocol
    # =================================================

    addqn_50_test_agent.step_scheduler()


    # =================================================
    # Same epsilon schedule
    # =================================================

    epsilon = max(
        0.05,
        epsilon * 0.995
    )


    avg_loss = (
        np.mean(losses)
        if losses
        else np.nan
    )


    print(
        f"Episode {episode+1:2d} | "
        f"Reward={total_reward:8.2f} | "
        f"RT={np.mean(response_times):7.2f} ms | "
        f"DMR={np.mean(deadline_misses):.3f} | "
        f"Overload={np.mean(overloads):.3f} | "
        f"Loss={avg_loss:9.2f} | "
        f"Eps={epsilon:.4f}"
    )


print("=" * 105)

print(
    "✅ 50-node smoke test completed"
)

print(
    "Replay buffer:",
    len(
        addqn_50_test_agent.memory
    )
)

print(
    "Training updates:",
    addqn_50_test_agent.training_steps
)

print(
    "Current LR:",
    addqn_50_test_agent.get_current_lr()
)

import os
import time
import random
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from ImprovedDQNAgent import ImprovedDQNAgent


# =====================================================
# ADDQN 50-NODE FULL TRAINING
# Scalability protocol
# =====================================================

NUM_NODES_50 = 50
STATE_DIM_50 = NUM_NODES_50 * 5
ACTION_DIM_50 = NUM_NODES_50

DT_50 = 15 / 50           # 0.30

EPISODES_50 = 500
MAX_STEPS_50 = 200


# =====================================================
# 1. Reproducibility
# =====================================================

set_global_seed(42)


# =====================================================
# 2. Output paths
# =====================================================

ADDQN50_CSV_PATH = os.path.join(
    SAVE_DIR,
    "ADDQN_50nodes_training_500episodes.csv"
)

ADDQN50_CHECKPOINT_PATH = os.path.join(
    SAVE_DIR,
    "ADDQN_50nodes_rolling_checkpoint.pt"
)

ADDQN50_FINAL_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "ADDQN_50nodes_final_model.pth"
)


# =====================================================
# 3. Environment
# =====================================================

env_50 = ImprovedFogSchedulingEnv(
    num_nodes=NUM_NODES_50,
    max_steps=MAX_STEPS_50,
    seed=42,
    dt=DT_50
)


# =====================================================
# 4. Fresh ADDQN Agent
# =====================================================

addqn_50_agent = ImprovedDQNAgent(
    state_dim=STATE_DIM_50,
    action_dim=ACTION_DIM_50,
    num_nodes=NUM_NODES_50,

    lr=3e-4,
    gamma=0.99,

    hidden_dim=128
)


PARAMS_50 = sum(
    p.numel()
    for p in addqn_50_agent.policy_net.parameters()
)


# =====================================================
# 5. Training configuration
# =====================================================

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

training_rows_50 = []


print("=" * 115)

print("🚀 ADDQN 50-NODE FULL TRAINING")

print(
    "Nodes:",
    NUM_NODES_50
)

print(
    "State dimension:",
    STATE_DIM_50
)

print(
    "Actions:",
    ACTION_DIM_50
)

print(
    "dt:",
    DT_50
)

print(
    "Episodes:",
    EPISODES_50
)

print(
    "Steps / episode:",
    MAX_STEPS_50
)

print(
    "Environment interactions:",
    EPISODES_50 * MAX_STEPS_50
)

print(
    "Parameters:",
    PARAMS_50
)

print(
    "Device:",
    addqn_50_agent.device
)

print("=" * 115)


training_start = time.time()


# =====================================================
# 6. Training Loop
# =====================================================

for episode in range(
    EPISODES_50
):

    episode_start = time.time()

    state = env_50.reset()


    # -------------------------------------------------
    # Episode metrics
    # -------------------------------------------------

    total_reward = 0.0

    response_times = []
    deadline_misses = []
    overloads = []

    avg_cpus = []
    avg_queues = []
    avg_energies = []
    chosen_latencies = []

    queue_imbalances = []

    losses = []


    # =================================================
    # 200 scheduling steps
    # =================================================

    for step in range(
        MAX_STEPS_50
    ):

        action = (
            addqn_50_agent.select_action(
                state,
                epsilon
            )
        )


        next_state, reward, done, info = (
            env_50.step(
                action
            )
        )


        # ---------------------------------------------
        # Replay
        # ---------------------------------------------

        addqn_50_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )


        # ---------------------------------------------
        # DDQN update
        # ---------------------------------------------

        loss = (
            addqn_50_agent.train(
                batch_size=64
            )
        )


        if loss is not None:

            losses.append(
                loss
            )


        # ---------------------------------------------
        # Metrics
        # ---------------------------------------------

        total_reward += reward

        response_times.append(
            info["response_time"]
        )

        deadline_misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        avg_cpus.append(
            info["avg_cpu"]
        )

        avg_queues.append(
            info["avg_queue_ms"]
        )

        avg_energies.append(
            info["avg_energy"]
        )

        chosen_latencies.append(
            info["latency"]
        )

        queue_imbalances.append(
            np.std(
                env_50.queue_ms
            )
            / env_50.queue_cap_ms
        )


        state = next_state


        if done:
            break


    # =================================================
    # Original target update convention
    # episode indices 0, 5, 10, ...
    # =================================================

    if episode % 5 == 0:

        addqn_50_agent.update_target()


    # =================================================
    # LR scheduler
    # =================================================

    addqn_50_agent.step_scheduler()


    # =================================================
    # Epsilon decay
    # =================================================

    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )


    # =================================================
    # Episode summary
    # =================================================

    avg_rt = float(
        np.mean(
            response_times
        )
    )

    dmr = float(
        np.mean(
            deadline_misses
        )
    )

    deadline_met = float(
        1.0 - dmr
    )

    overload_ratio = float(
        np.mean(
            overloads
        )
    )

    energy_depletion = float(
        np.sum(
            1.0 - env_50.energy
        )
    )

    load_imbalance = float(
        np.mean(
            queue_imbalances
        )
    )

    avg_loss = float(
        np.mean(losses)
    ) if losses else np.nan

    episode_time = float(
        time.time()
        - episode_start
    )


    training_rows_50.append({

        "episode":
            episode + 1,

        "num_nodes":
            NUM_NODES_50,

        "dt":
            DT_50,

        "total_reward":
            float(total_reward),

        "avg_rt":
            avg_rt,

        "dmr":
            dmr,

        "deadline_met_ratio":
            deadline_met,

        "overload_ratio":
            overload_ratio,

        "energy_depletion":
            energy_depletion,

        "load_imbalance":
            load_imbalance,

        "avg_cpu":
            float(
                np.mean(avg_cpus)
            ),

        "avg_queue_ms":
            float(
                np.mean(avg_queues)
            ),

        "avg_energy":
            float(
                np.mean(avg_energies)
            ),

        "chosen_latency":
            float(
                np.mean(chosen_latencies)
            ),

        "avg_loss":
            avg_loss,

        "epsilon":
            epsilon,

        "learning_rate":
            addqn_50_agent.get_current_lr(),

        "training_steps":
            addqn_50_agent.training_steps,

        "episode_time_sec":
            episode_time
    })


    # =================================================
    # Progress
    # =================================================

    if (
        episode == 0
        or (episode + 1) % 10 == 0
    ):

        recent = pd.DataFrame(
            training_rows_50
        ).tail(10)

        print(
            f"Ep {episode+1:3d}/500 | "
            f"R={recent['total_reward'].mean():8.1f} | "
            f"RT={recent['avg_rt'].mean():7.2f} | "
            f"DMR={recent['dmr'].mean():.3f} | "
            f"Met={recent['deadline_met_ratio'].mean():.3f} | "
            f"Loss={recent['avg_loss'].mean():9.2f} | "
            f"Eps={epsilon:.4f} | "
            f"LR={addqn_50_agent.get_current_lr():.6f}"
        )


    # =================================================
    # Save CSV every 10 episodes
    # =================================================

    if (
        (episode + 1) % 10 == 0
    ):

        pd.DataFrame(
            training_rows_50
        ).to_csv(
            ADDQN50_CSV_PATH,
            index=False
        )


    # =================================================
    # Rolling checkpoint every 25 episodes
    # =================================================

    if (
        (episode + 1) % 25 == 0
        or episode == EPISODES_50 - 1
    ):

        checkpoint = {

            "episode_index":
                episode,

            "num_nodes":
                NUM_NODES_50,

            "state_dim":
                STATE_DIM_50,

            "action_dim":
                ACTION_DIM_50,

            "dt":
                DT_50,

            "policy_net_state_dict":
                addqn_50_agent
                .policy_net
                .state_dict(),

            "target_net_state_dict":
                addqn_50_agent
                .target_net
                .state_dict(),

            "optimizer_state_dict":
                addqn_50_agent
                .optimizer
                .state_dict(),

            "scheduler_state_dict":
                addqn_50_agent
                .scheduler
                .state_dict(),

            "training_steps":
                addqn_50_agent.training_steps,

            "epsilon":
                epsilon,

            "python_random_state":
                random.getstate(),

            "numpy_random_state":
                np.random.get_state(),

            "torch_random_state":
                torch.get_rng_state(),

            "cuda_random_state":
                (
                    torch.cuda.get_rng_state_all()
                    if torch.cuda.is_available()
                    else None
                ),

            "env_rng_state":
                env_50.rng.bit_generator.state,

            "training_rows":
                training_rows_50
        }


        torch.save(
            checkpoint,
            ADDQN50_CHECKPOINT_PATH
        )


        print(
            f"   💾 checkpoint saved "
            f"at episode {episode+1}"
        )


# =====================================================
# 7. Save final CSV
# =====================================================

addqn_50_training_df = pd.DataFrame(
    training_rows_50
)

addqn_50_training_df.to_csv(
    ADDQN50_CSV_PATH,
    index=False
)


# =====================================================
# 8. Save final model
# =====================================================

torch.save(
    {

        "algorithm":
            "ADDQN",

        "num_nodes":
            NUM_NODES_50,

        "state_dim":
            STATE_DIM_50,

        "action_dim":
            ACTION_DIM_50,

        "dt":
            DT_50,

        "hidden_dim":
            128,

        "parameters":
            PARAMS_50,

        "policy_net_state_dict":
            addqn_50_agent
            .policy_net
            .state_dict(),

        "target_net_state_dict":
            addqn_50_agent
            .target_net
            .state_dict(),

        "optimizer_state_dict":
            addqn_50_agent
            .optimizer
            .state_dict(),

        "scheduler_state_dict":
            addqn_50_agent
            .scheduler
            .state_dict(),

        "training_steps":
            addqn_50_agent.training_steps,

        "final_epsilon":
            epsilon,

        "episodes":
            EPISODES_50,

        "max_steps":
            MAX_STEPS_50,

        "environment_interactions":
            EPISODES_50
            * MAX_STEPS_50
    },

    ADDQN50_FINAL_MODEL_PATH
)


# =====================================================
# 9. Final summary
# =====================================================

total_training_time_50 = (
    time.time()
    - training_start
)


print("\n" + "=" * 115)

print(
    "✅ ADDQN 50-NODE TRAINING COMPLETE"
)

print(
    f"Training time: "
    f"{total_training_time_50/60:.2f} minutes"
)

print(
    "Environment interactions:",
    EPISODES_50
    * MAX_STEPS_50
)

print(
    "Replay buffer:",
    len(
        addqn_50_agent.memory
    )
)

print(
    "Training updates:",
    addqn_50_agent.training_steps
)

print(
    f"Final epsilon: "
    f"{epsilon:.4f}"
)

print(
    f"Final LR: "
    f"{addqn_50_agent.get_current_lr():.8f}"
)

print(
    "Parameters:",
    PARAMS_50
)

print("\nLast 50 episodes:")

last50 = (
    addqn_50_training_df
    .tail(50)
)

print(
    f"Reward: "
    f"{last50['total_reward'].mean():.2f}"
)

print(
    f"RT: "
    f"{last50['avg_rt'].mean():.2f} ms"
)

print(
    f"DMR: "
    f"{last50['dmr'].mean():.4f}"
)

print(
    f"Deadline Met: "
    f"{last50['deadline_met_ratio'].mean()*100:.2f}%"
)

print("\nSaved files:")

print(
    "📊",
    ADDQN50_CSV_PATH
)

print(
    "🧠",
    ADDQN50_FINAL_MODEL_PATH
)

print(
    "💾",
    ADDQN50_CHECKPOINT_PATH
)

