import os
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from VanillaDDQNAgent import VanillaDDQNAgent


# =====================================================
# VANILLA DDQN 50-NODE FIXED-TOPOLOGY EVALUATION
# Same protocol as ADDQN-50
# =====================================================

NUM_NODES_50 = 50
STATE_DIM_50 = 250
ACTION_DIM_50 = 50
DT_50 = 15 / 50

TASK_SEEDS_50 = list(
    range(100, 130)
)


# =====================================================
# Use trained agent or load saved model
# =====================================================

try:

    ddqn_50_eval_agent = ddqn_50_agent

    print(
        "✅ Using existing trained DDQN-50 agent"
    )

except NameError:

    ddqn_50_eval_agent = VanillaDDQNAgent(
        state_dim=STATE_DIM_50,
        action_dim=ACTION_DIM_50,
        lr=3e-4,
        gamma=0.99
    )

    checkpoint = torch.load(
        DDQN50_FINAL_MODEL_PATH,
        map_location=ddqn_50_eval_agent.device
    )

    ddqn_50_eval_agent.policy_net.load_state_dict(
        checkpoint["policy_net_state_dict"]
    )

    ddqn_50_eval_agent.target_net.load_state_dict(
        checkpoint["target_net_state_dict"]
    )

    print(
        "✅ DDQN-50 model loaded from disk"
    )


ddqn_50_eval_agent.policy_net.eval()


# =====================================================
# Evaluation
# =====================================================

rows = []


for task_seed in TASK_SEEDS_50:

    env = ImprovedFogSchedulingEnv(
        num_nodes=NUM_NODES_50,
        max_steps=200,
        seed=42,
        dt=DT_50
    )

    # Same topology, independent task stream
    env.rng = np.random.default_rng(
        task_seed
    )

    state = env.reset()

    rewards = []
    response_times = []
    misses = []
    overloads = []
    queue_imbalances = []

    action_counts = np.zeros(
        NUM_NODES_50,
        dtype=np.int64
    )


    for step in range(
        env.max_steps
    ):

        action = (
            ddqn_50_eval_agent.select_action(
                state,
                epsilon=0.0
            )
        )

        action_counts[action] += 1

        next_state, reward, done, info = (
            env.step(action)
        )

        rewards.append(reward)

        response_times.append(
            info["response_time"]
        )

        misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        queue_imbalances.append(
            np.std(env.queue_ms)
            / env.queue_cap_ms
        )

        state = next_state

        if done:
            break


    probs = (
        action_counts
        / action_counts.sum()
    )

    nz = probs[
        probs > 0
    ]

    action_entropy = float(
        -np.sum(
            nz * np.log(nz)
        )
        / np.log(NUM_NODES_50)
    )

    dmr = float(
        np.mean(misses)
    )


    rows.append({

        "method":
            "Vanilla DDQN",

        "task_seed":
            task_seed,

        "avg_rt":
            float(
                np.mean(response_times)
            ),

        "dmr":
            dmr,

        "deadline_met_ratio":
            1.0 - dmr,

        "avg_reward":
            float(
                np.mean(rewards)
            ),

        "energy_depletion":
            float(
                np.sum(
                    1.0 - env.energy
                )
            ),

        "load_imbalance":
            float(
                np.mean(
                    queue_imbalances
                )
            ),

        "overload_ratio":
            float(
                np.mean(overloads)
            ),

        "action_entropy":
            action_entropy,

        "dominant_node":
            int(
                np.argmax(probs)
            ),

        "dominant_node_share":
            float(
                probs.max()
            ),

        "active_nodes":
            int(
                np.sum(
                    action_counts > 0
                )
            )
    })


ddqn_50_matched = pd.DataFrame(
    rows
)


# =====================================================
# Summary
# =====================================================

print(
    "\n"
    + "=" * 85
)

print(
    "📊 VANILLA DDQN 50-NODE FIXED-TOPOLOGY EVALUATION"
)

print(
    "=" * 85
)

print(
    f"RT: "
    f"{ddqn_50_matched['avg_rt'].mean():.2f} "
    f"± "
    f"{ddqn_50_matched['avg_rt'].std(ddof=1):.2f} ms"
)

print(
    f"DMR: "
    f"{ddqn_50_matched['dmr'].mean():.4f} "
    f"± "
    f"{ddqn_50_matched['dmr'].std(ddof=1):.4f}"
)

print(
    f"Deadline Met: "
    f"{ddqn_50_matched['deadline_met_ratio'].mean()*100:.2f}% "
    f"± "
    f"{ddqn_50_matched['deadline_met_ratio'].std(ddof=1)*100:.2f}%"
)

print(
    f"Reward: "
    f"{ddqn_50_matched['avg_reward'].mean():.4f} "
    f"± "
    f"{ddqn_50_matched['avg_reward'].std(ddof=1):.4f}"
)

print(
    f"Energy depletion: "
    f"{ddqn_50_matched['energy_depletion'].mean():.6f}"
)

print(
    f"Load imbalance: "
    f"{ddqn_50_matched['load_imbalance'].mean():.6f}"
)

print(
    f"Overload ratio: "
    f"{ddqn_50_matched['overload_ratio'].mean():.4f}"
)

print(
    f"Action entropy: "
    f"{ddqn_50_matched['action_entropy'].mean():.4f}"
)

print(
    f"Dominant-node share: "
    f"{ddqn_50_matched['dominant_node_share'].mean()*100:.2f}%"
)

print(
    f"Active nodes: "
    f"{ddqn_50_matched['active_nodes'].mean():.2f} "
    f"± "
    f"{ddqn_50_matched['active_nodes'].std(ddof=1):.2f}"
)


# =====================================================
# Save
# =====================================================

DDQN50_EVAL_PATH = os.path.join(
    SAVE_DIR,
    "Vanilla_DDQN_50nodes_fixed_topology_30runs.csv"
)

ddqn_50_matched.to_csv(
    DDQN50_EVAL_PATH,
    index=False
)

print("\n✅ Saved:")
print(
    DDQN50_EVAL_PATH
)

import pandas as pd
import numpy as np


# =====================================================
# DDQN-50 TRAINING COLLAPSE DIAGNOSTIC
# =====================================================

ddqn50_log = pd.read_csv(
    DDQN50_CSV_PATH
)


print("✅ DDQN-50 log loaded")
print("Episodes:", len(ddqn50_log))


# =====================================================
# 50-episode blocks
# =====================================================

ddqn50_log["block"] = (
    (ddqn50_log["episode"] - 1)
    // 50
    + 1
)


block_summary = (
    ddqn50_log
    .groupby("block")
    .agg(

        episode_start=(
            "episode",
            "min"
        ),

        episode_end=(
            "episode",
            "max"
        ),

        reward_mean=(
            "total_reward",
            "mean"
        ),

        rt_mean=(
            "avg_rt",
            "mean"
        ),

        dmr_mean=(
            "dmr",
            "mean"
        ),

        loss_mean=(
            "avg_loss",
            "mean"
        ),

        load_mean=(
            "load_imbalance",
            "mean"
        ),

        overload_mean=(
            "overload_ratio",
            "mean"
        ),

        epsilon_mean=(
            "epsilon",
            "mean"
        )
    )
    .reset_index()
)


print("\n📊 50-episode blocks")

display(
    block_summary.round(4)
)


# =====================================================
# Best 20-episode windows
# =====================================================

ddqn50_log[
    "rolling_reward_20"
] = (
    ddqn50_log[
        "total_reward"
    ]
    .rolling(20)
    .mean()
)

ddqn50_log[
    "rolling_rt_20"
] = (
    ddqn50_log[
        "avg_rt"
    ]
    .rolling(20)
    .mean()
)

ddqn50_log[
    "rolling_dmr_20"
] = (
    ddqn50_log[
        "dmr"
    ]
    .rolling(20)
    .mean()
)


best_reward_idx = (
    ddqn50_log[
        "rolling_reward_20"
    ]
    .idxmax()
)

best_rt_idx = (
    ddqn50_log[
        "rolling_rt_20"
    ]
    .idxmin()
)

best_dmr_idx = (
    ddqn50_log[
        "rolling_dmr_20"
    ]
    .idxmin()
)


print("\n🏆 Best 20-episode windows")

print(
    "Best reward ending episode:",
    int(
        ddqn50_log.loc[
            best_reward_idx,
            "episode"
        ]
    ),
    "| Reward:",
    round(
        ddqn50_log.loc[
            best_reward_idx,
            "rolling_reward_20"
        ],
        2
    )
)

print(
    "Best RT ending episode:",
    int(
        ddqn50_log.loc[
            best_rt_idx,
            "episode"
        ]
    ),
    "| RT:",
    round(
        ddqn50_log.loc[
            best_rt_idx,
            "rolling_rt_20"
        ],
        2
    )
)

print(
    "Best DMR ending episode:",
    int(
        ddqn50_log.loc[
            best_dmr_idx,
            "episode"
        ]
    ),
    "| DMR:",
    round(
        ddqn50_log.loc[
            best_dmr_idx,
            "rolling_dmr_20"
        ],
        4
    )
)


# =====================================================
# Final 20 episodes
# =====================================================

print("\n📌 Final 20 episodes")

display(
    ddqn50_log[
        [
            "episode",
            "total_reward",
            "avg_rt",
            "dmr",
            "load_imbalance",
            "overload_ratio",
            "avg_loss",
            "epsilon"
        ]
    ]
    .tail(20)
    .round(5)
)

import os
import time
import numpy as np
import pandas as pd
import torch
import torch.nn as nn

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from VanillaDDQNAgent import VanillaDDQNAgent


# =====================================================
# ONE PREDECLARED DDQN-50 STABILIZATION PILOT
#
# Changes ONLY:
#   lr:   3e-4 -> 1e-4
#   loss: MSE   -> Huber
#
# Everything else remains identical.
# =====================================================

NUM_NODES = 50
STATE_DIM = 250
ACTION_DIM = 50

DT = 15 / 50

EPISODES = 150
MAX_STEPS = 200


# =====================================================
# Reproducibility
# =====================================================

set_global_seed(42)


# =====================================================
# Environment
# =====================================================

stable_env = ImprovedFogSchedulingEnv(
    num_nodes=NUM_NODES,
    max_steps=MAX_STEPS,
    seed=42,
    dt=DT
)


# =====================================================
# Agent
# =====================================================

stable_agent = VanillaDDQNAgent(
    state_dim=STATE_DIM,
    action_dim=ACTION_DIM,
    lr=1e-4,
    gamma=0.99
)


# =====================================================
# Replace MSE with Huber
# =====================================================

print(
    "Original loss:",
    stable_agent.loss_fn
)

stable_agent.loss_fn = (
    nn.SmoothL1Loss()
)

print(
    "Pilot loss:",
    stable_agent.loss_fn
)


# =====================================================
# Training
# =====================================================

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

rows = []

start_time = time.time()


print("\n" + "=" * 105)

print(
    "🧪 DDQN-50 STABILIZATION PILOT"
)

print(
    "LR = 1e-4 | Huber loss | "
    "150 episodes"
)

print("=" * 105)


for episode in range(EPISODES):

    state = stable_env.reset()

    total_reward = 0.0

    rts = []
    misses = []
    overloads = []
    imbalances = []
    losses = []


    for step in range(MAX_STEPS):

        action = stable_agent.select_action(
            state,
            epsilon
        )

        next_state, reward, done, info = (
            stable_env.step(action)
        )


        stable_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )


        loss = stable_agent.train(
            batch_size=64
        )


        if loss is not None:

            losses.append(loss)


        total_reward += reward

        rts.append(
            info["response_time"]
        )

        misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        imbalances.append(
            np.std(
                stable_env.queue_ms
            )
            / stable_env.queue_cap_ms
        )


        state = next_state


        if done:
            break


    # ---------------------------------------------
    # Same target update
    # ---------------------------------------------

    if episode % 5 == 0:

        stable_agent.update_target()


    # ---------------------------------------------
    # Same scheduler
    # ---------------------------------------------

    stable_agent.step_scheduler()


    # ---------------------------------------------
    # Same epsilon decay
    # ---------------------------------------------

    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )


    rows.append({

        "episode":
            episode + 1,

        "reward":
            total_reward,

        "rt":
            np.mean(rts),

        "dmr":
            np.mean(misses),

        "overload":
            np.mean(overloads),

        "load_imbalance":
            np.mean(imbalances),

        "loss":
            (
                np.mean(losses)
                if losses
                else np.nan
            ),

        "epsilon":
            epsilon
    })


    if (
        episode == 0
        or (episode + 1) % 10 == 0
    ):

        recent = pd.DataFrame(
            rows
        ).tail(10)

        print(
            f"Ep {episode+1:3d}/150 | "
            f"R={recent['reward'].mean():8.1f} | "
            f"RT={recent['rt'].mean():7.2f} | "
            f"DMR={recent['dmr'].mean():.3f} | "
            f"Over={recent['overload'].mean():.3f} | "
            f"Load={recent['load_imbalance'].mean():.4f} | "
            f"Loss={recent['loss'].mean():8.2f} | "
            f"Eps={epsilon:.3f}"
        )


# =====================================================
# Training DataFrame
# =====================================================

stable_df = pd.DataFrame(rows)


# =====================================================
# 50-episode blocks
# =====================================================

stable_df["block"] = (
    (stable_df["episode"] - 1)
    // 50
    + 1
)


block_summary = (
    stable_df
    .groupby("block")
    .agg(

        reward_mean=(
            "reward",
            "mean"
        ),

        rt_mean=(
            "rt",
            "mean"
        ),

        dmr_mean=(
            "dmr",
            "mean"
        ),

        overload_mean=(
            "overload",
            "mean"
        ),

        load_mean=(
            "load_imbalance",
            "mean"
        ),

        loss_mean=(
            "loss",
            "mean"
        )
    )
    .reset_index()
)


print(
    "\n📊 50-episode blocks"
)

display(
    block_summary.round(4)
)


# =====================================================
# Deterministic validation
# Separate tuning seeds 700-709
# =====================================================

validation_rows = []


stable_agent.policy_net.eval()


for task_seed in range(
    700,
    710
):

    env = ImprovedFogSchedulingEnv(
        num_nodes=50,
        max_steps=200,
        seed=42,
        dt=DT
    )

    env.rng = np.random.default_rng(
        task_seed
    )

    state = env.reset()

    rts = []
    misses = []
    rewards = []

    action_counts = np.zeros(
        50,
        dtype=np.int64
    )


    for step in range(200):

        action = (
            stable_agent.select_action(
                state,
                epsilon=0.0
            )
        )

        action_counts[action] += 1

        next_state, reward, done, info = (
            env.step(action)
        )

        rewards.append(reward)

        rts.append(
            info["response_time"]
        )

        misses.append(
            info["deadline_miss"]
        )

        state = next_state

        if done:
            break


    probs = (
        action_counts
        / action_counts.sum()
    )


    validation_rows.append({

        "task_seed":
            task_seed,

        "reward":
            np.mean(rewards),

        "rt":
            np.mean(rts),

        "dmr":
            np.mean(misses),

        "dominant_share":
            probs.max(),

        "active_nodes":
            np.sum(
                action_counts > 0
            )
    })


validation_df = pd.DataFrame(
    validation_rows
)


print(
    "\n"
    + "=" * 90
)

print(
    "🔎 DDQN-50 STABILIZATION VALIDATION"
)

print("=" * 90)


print(
    f"RT: "
    f"{validation_df['rt'].mean():.2f} "
    f"± "
    f"{validation_df['rt'].std(ddof=1):.2f} ms"
)

print(
    f"DMR: "
    f"{validation_df['dmr'].mean():.4f} "
    f"± "
    f"{validation_df['dmr'].std(ddof=1):.4f}"
)

print(
    f"Reward: "
    f"{validation_df['reward'].mean():.4f}"
)

print(
    f"Dominant-node share: "
    f"{validation_df['dominant_share'].mean()*100:.2f}%"
)

print(
    f"Active nodes: "
    f"{validation_df['active_nodes'].mean():.2f}"
)


# =====================================================
# Save pilot
# =====================================================

STABLE_DDQN50_PILOT_PATH = os.path.join(
    SAVE_DIR,
    "DDQN_50nodes_stabilization_pilot_150ep.csv"
)

STABLE_DDQN50_VALIDATION_PATH = os.path.join(
    SAVE_DIR,
    "DDQN_50nodes_stabilization_validation.csv"
)


stable_df.to_csv(
    STABLE_DDQN50_PILOT_PATH,
    index=False
)

validation_df.to_csv(
    STABLE_DDQN50_VALIDATION_PATH,
    index=False
)


print(
    "\nTraining time:",
    round(
        (
            time.time()
            - start_time
        ) / 60,
        2
    ),
    "minutes"
)

print("\n✅ Saved:")
print(STABLE_DDQN50_PILOT_PATH)
print(STABLE_DDQN50_VALIDATION_PATH)

import os
import time
import random
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from VanillaDQNAgent import VanillaDQNAgent


# =====================================================
# VANILLA DQN 50-NODE FULL TRAINING
# Same protocol as ADDQN-50 / DDQN-50
# =====================================================

NUM_NODES = 50
STATE_DIM = 250
ACTION_DIM = 50

DT = 15 / 50

EPISODES = 500
MAX_STEPS = 200


# =====================================================
# Reproducibility
# =====================================================

set_global_seed(42)


# =====================================================
# Paths
# =====================================================

DQN50_CSV_PATH = os.path.join(
    SAVE_DIR,
    "Vanilla_DQN_50nodes_training_500episodes.csv"
)

DQN50_CHECKPOINT_PATH = os.path.join(
    SAVE_DIR,
    "Vanilla_DQN_50nodes_rolling_checkpoint.pt"
)

DQN50_FINAL_MODEL_PATH = os.path.join(
    SAVE_DIR,
    "Vanilla_DQN_50nodes_final_model.pth"
)


# =====================================================
# Environment
# =====================================================

dqn_50_env = ImprovedFogSchedulingEnv(
    num_nodes=NUM_NODES,
    max_steps=MAX_STEPS,
    seed=42,
    dt=DT
)


# =====================================================
# Agent
# =====================================================

dqn_50_agent = VanillaDQNAgent(
    state_dim=STATE_DIM,
    action_dim=ACTION_DIM,
    lr=3e-4,
    gamma=0.99
)


DQN50_PARAMS = sum(
    p.numel()
    for p in dqn_50_agent.policy_net.parameters()
)


epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

rows = []

start_time = time.time()


print("=" * 110)

print("🚀 VANILLA DQN 50-NODE FULL TRAINING")

print("Parameters:", DQN50_PARAMS)
print("dt:", DT)

print(
    "Environment interactions:",
    EPISODES * MAX_STEPS
)

print("=" * 110)


# =====================================================
# Training
# =====================================================

for episode in range(EPISODES):

    state = dqn_50_env.reset()

    total_reward = 0.0

    rts = []
    misses = []
    overloads = []
    imbalances = []
    losses = []


    for step in range(MAX_STEPS):

        action = (
            dqn_50_agent.select_action(
                state,
                epsilon
            )
        )


        next_state, reward, done, info = (
            dqn_50_env.step(action)
        )


        dqn_50_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )


        loss = dqn_50_agent.train(
            batch_size=64
        )


        if loss is not None:
            losses.append(loss)


        total_reward += reward

        rts.append(
            info["response_time"]
        )

        misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        imbalances.append(
            np.std(
                dqn_50_env.queue_ms
            )
            / dqn_50_env.queue_cap_ms
        )


        state = next_state


        if done:
            break


    # target update
    if episode % 5 == 0:
        dqn_50_agent.update_target()


    # LR scheduler
    dqn_50_agent.step_scheduler()


    # epsilon
    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )


    rows.append({

        "episode":
            episode + 1,

        "total_reward":
            total_reward,

        "avg_rt":
            np.mean(rts),

        "dmr":
            np.mean(misses),

        "deadline_met_ratio":
            1.0 - np.mean(misses),

        "overload_ratio":
            np.mean(overloads),

        "load_imbalance":
            np.mean(imbalances),

        "avg_loss":
            (
                np.mean(losses)
                if losses
                else np.nan
            ),

        "epsilon":
            epsilon,

        "learning_rate":
            dqn_50_agent.get_current_lr(),

        "training_steps":
            dqn_50_agent.training_steps
    })


    if (
        episode == 0
        or (episode + 1) % 10 == 0
    ):

        recent = pd.DataFrame(
            rows
        ).tail(10)

        print(
            f"Ep {episode+1:3d}/500 | "
            f"R={recent['total_reward'].mean():8.1f} | "
            f"RT={recent['avg_rt'].mean():7.2f} | "
            f"DMR={recent['dmr'].mean():.3f} | "
            f"Over={recent['overload_ratio'].mean():.3f} | "
            f"Loss={recent['avg_loss'].mean():9.2f} | "
            f"Eps={epsilon:.4f}"
        )


    if (episode + 1) % 10 == 0:

        pd.DataFrame(
            rows
        ).to_csv(
            DQN50_CSV_PATH,
            index=False
        )


    if (
        (episode + 1) % 25 == 0
        or episode == EPISODES - 1
    ):

        torch.save(
            {
                "episode_index":
                    episode,

                "policy_net_state_dict":
                    dqn_50_agent.policy_net.state_dict(),

                "target_net_state_dict":
                    dqn_50_agent.target_net.state_dict(),

                "optimizer_state_dict":
                    dqn_50_agent.optimizer.state_dict(),

                "scheduler_state_dict":
                    dqn_50_agent.scheduler.state_dict(),

                "epsilon":
                    epsilon,

                "training_steps":
                    dqn_50_agent.training_steps,

                "num_nodes":
                    NUM_NODES,

                "dt":
                    DT
            },
            DQN50_CHECKPOINT_PATH
        )


# =====================================================
# Save final
# =====================================================

dqn_50_training_df = pd.DataFrame(rows)

dqn_50_training_df.to_csv(
    DQN50_CSV_PATH,
    index=False
)


torch.save(
    {
        "algorithm":
            "Vanilla DQN",

        "num_nodes":
            NUM_NODES,

        "state_dim":
            STATE_DIM,

        "action_dim":
            ACTION_DIM,

        "dt":
            DT,

        "parameters":
            DQN50_PARAMS,

        "policy_net_state_dict":
            dqn_50_agent.policy_net.state_dict(),

        "target_net_state_dict":
            dqn_50_agent.target_net.state_dict(),

        "optimizer_state_dict":
            dqn_50_agent.optimizer.state_dict(),

        "scheduler_state_dict":
            dqn_50_agent.scheduler.state_dict(),

        "training_steps":
            dqn_50_agent.training_steps,

        "final_epsilon":
            epsilon,

        "environment_interactions":
            EPISODES * MAX_STEPS
    },
    DQN50_FINAL_MODEL_PATH
)


# =====================================================
# Summary
# =====================================================

last50 = (
    dqn_50_training_df.tail(50)
)

training_minutes = (
    time.time()
    - start_time
) / 60


print("\n" + "=" * 110)

print(
    "✅ VANILLA DQN 50-NODE TRAINING COMPLETE"
)

print(
    f"Training time: "
    f"{training_minutes:.2f} minutes"
)

print(
    "Parameters:",
    DQN50_PARAMS
)

print(
    "Training updates:",
    dqn_50_agent.training_steps
)

print(
    f"Final epsilon: "
    f"{epsilon:.4f}"
)

print("\nLast 50 episodes:")

print(
    f"Reward: "
    f"{last50['total_reward'].mean():.2f}"
)

print(
    f"RT: "
    f"{last50['avg_rt'].mean():.2f} ms"
)

print(
    f"DMR: "
    f"{last50['dmr'].mean():.4f}"
)

print(
    f"Deadline Met: "
    f"{last50['deadline_met_ratio'].mean()*100:.2f}%"
)

print("=" * 110)

import os
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv
from VanillaDQNAgent import VanillaDQNAgent


# =====================================================
# VANILLA DQN 50-NODE FIXED-TOPOLOGY EVALUATION
# Same exact protocol as ADDQN-50 and DDQN-50
# =====================================================

NUM_NODES_50 = 50
STATE_DIM_50 = 250
ACTION_DIM_50 = 50

DT_50 = 15 / 50

TASK_SEEDS_50 = list(
    range(100, 130)
)


# =====================================================
# Use trained agent or reload
# =====================================================

try:

    dqn_50_eval_agent = dqn_50_agent

    print(
        "✅ Using existing trained DQN-50 agent"
    )

except NameError:

    dqn_50_eval_agent = VanillaDQNAgent(
        state_dim=STATE_DIM_50,
        action_dim=ACTION_DIM_50,
        lr=3e-4,
        gamma=0.99
    )

    checkpoint = torch.load(
        DQN50_FINAL_MODEL_PATH,
        map_location=dqn_50_eval_agent.device
    )

    dqn_50_eval_agent.policy_net.load_state_dict(
        checkpoint["policy_net_state_dict"]
    )

    dqn_50_eval_agent.target_net.load_state_dict(
        checkpoint["target_net_state_dict"]
    )

    print(
        "✅ DQN-50 model loaded from disk"
    )


dqn_50_eval_agent.policy_net.eval()


# =====================================================
# Evaluation
# =====================================================

rows = []


for task_seed in TASK_SEEDS_50:

    env = ImprovedFogSchedulingEnv(
        num_nodes=NUM_NODES_50,
        max_steps=200,
        seed=42,
        dt=DT_50
    )

    # Same topology, independent task stream
    env.rng = np.random.default_rng(
        task_seed
    )

    state = env.reset()


    rewards = []
    response_times = []
    misses = []
    overloads = []
    queue_imbalances = []

    action_counts = np.zeros(
        NUM_NODES_50,
        dtype=np.int64
    )


    for step in range(
        env.max_steps
    ):

        action = (
            dqn_50_eval_agent.select_action(
                state,
                epsilon=0.0
            )
        )

        action_counts[action] += 1


        next_state, reward, done, info = (
            env.step(action)
        )


        rewards.append(
            reward
        )

        response_times.append(
            info["response_time"]
        )

        misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        queue_imbalances.append(
            np.std(
                env.queue_ms
            )
            / env.queue_cap_ms
        )


        state = next_state


        if done:
            break


    # =================================================
    # Action distribution
    # =================================================

    probs = (
        action_counts
        / action_counts.sum()
    )

    nz = probs[
        probs > 0
    ]

    action_entropy = float(
        -np.sum(
            nz * np.log(nz)
        )
        / np.log(
            NUM_NODES_50
        )
    )


    dmr = float(
        np.mean(
            misses
        )
    )


    rows.append({

        "method":
            "Vanilla DQN",

        "task_seed":
            task_seed,

        "avg_rt":
            float(
                np.mean(
                    response_times
                )
            ),

        "dmr":
            dmr,

        "deadline_met_ratio":
            1.0 - dmr,

        "avg_reward":
            float(
                np.mean(
                    rewards
                )
            ),

        "energy_depletion":
            float(
                np.sum(
                    1.0 - env.energy
                )
            ),

        "load_imbalance":
            float(
                np.mean(
                    queue_imbalances
                )
            ),

        "overload_ratio":
            float(
                np.mean(
                    overloads
                )
            ),

        "action_entropy":
            action_entropy,

        "dominant_node":
            int(
                np.argmax(
                    probs
                )
            ),

        "dominant_node_share":
            float(
                probs.max()
            ),

        "active_nodes":
            int(
                np.sum(
                    action_counts > 0
                )
            )
    })


# =====================================================
# DataFrame
# =====================================================

dqn_50_matched = pd.DataFrame(
    rows
)


# =====================================================
# Summary
# =====================================================

print(
    "\n"
    + "=" * 85
)

print(
    "📊 VANILLA DQN 50-NODE FIXED-TOPOLOGY EVALUATION"
)

print(
    "=" * 85
)


print(
    f"RT: "
    f"{dqn_50_matched['avg_rt'].mean():.2f} "
    f"± "
    f"{dqn_50_matched['avg_rt'].std(ddof=1):.2f} ms"
)

print(
    f"DMR: "
    f"{dqn_50_matched['dmr'].mean():.4f} "
    f"± "
    f"{dqn_50_matched['dmr'].std(ddof=1):.4f}"
)

print(
    f"Deadline Met: "
    f"{dqn_50_matched['deadline_met_ratio'].mean()*100:.2f}% "
    f"± "
    f"{dqn_50_matched['deadline_met_ratio'].std(ddof=1)*100:.2f}%"
)

print(
    f"Reward: "
    f"{dqn_50_matched['avg_reward'].mean():.4f} "
    f"± "
    f"{dqn_50_matched['avg_reward'].std(ddof=1):.4f}"
)

print(
    f"Energy depletion: "
    f"{dqn_50_matched['energy_depletion'].mean():.6f}"
)

print(
    f"Load imbalance: "
    f"{dqn_50_matched['load_imbalance'].mean():.6f}"
)

print(
    f"Overload ratio: "
    f"{dqn_50_matched['overload_ratio'].mean():.4f}"
)

print(
    f"Action entropy: "
    f"{dqn_50_matched['action_entropy'].mean():.4f}"
)

print(
    f"Dominant-node share: "
    f"{dqn_50_matched['dominant_node_share'].mean()*100:.2f}%"
)

print(
    f"Active nodes: "
    f"{dqn_50_matched['active_nodes'].mean():.2f} "
    f"± "
    f"{dqn_50_matched['active_nodes'].std(ddof=1):.2f}"
)


# =====================================================
