import os
import random
import numpy as np
import pandas as pd
import torch

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv


# =====================================================
# PPO-50 STOCHASTIC FIXED-TOPOLOGY EVALUATION
#
# 30 task seeds
# × 5 stochastic policy seeds
# = 150 raw runs
#
# Then average the 5 policy replicates
# within each task seed -> N = 30 matched observations
# =====================================================

NUM_NODES_50 = 50
DT_50 = 15 / 50

TASK_SEEDS = list(
    range(100, 130)
)

POLICY_SEEDS = [
    6001,
    6002,
    6003,
    6004,
    6005
]


# =====================================================
# Evaluation mode
# =====================================================

ppo_50_agent.net.eval()


raw_rows = []


# =====================================================
# 150 stochastic runs
# =====================================================

for task_seed in TASK_SEEDS:

    for policy_seed in POLICY_SEEDS:

        # ---------------------------------------------
        # Seed ONLY policy sampling
        # Environment uses its independent Generator
        # ---------------------------------------------

        torch.manual_seed(
            policy_seed
        )

        if torch.cuda.is_available():

            torch.cuda.manual_seed_all(
                policy_seed
            )


        # ---------------------------------------------
        # Same fixed topology
        # ---------------------------------------------

        env = ImprovedFogSchedulingEnv(
            num_nodes=NUM_NODES_50,
            max_steps=200,
            seed=42,
            dt=DT_50
        )


        # ---------------------------------------------
        # Same task stream for all algorithms
        # ---------------------------------------------

        env.rng = np.random.default_rng(
            task_seed
        )

        state = env.reset()


        rewards = []
        response_times = []
        misses = []
        overloads = []
        queue_imbalances = []


        action_counts = np.zeros(
            NUM_NODES_50,
            dtype=np.int64
        )


        # =============================================
        # Episode
        # =============================================

        for step in range(
            env.max_steps
        ):

            action, _, _ = (
                ppo_50_agent.select_action(
                    state
                )
            )


            action_counts[
                action
            ] += 1


            next_state, reward, done, info = (
                env.step(
                    action
                )
            )


            rewards.append(
                reward
            )

            response_times.append(
                info["response_time"]
            )

            misses.append(
                info["deadline_miss"]
            )

            overloads.append(
                info["overload"]
            )


            queue_imbalances.append(

                np.std(
                    env.queue_ms
                )
                / env.queue_cap_ms
            )


            state = next_state


            if done:
                break


        # =============================================
        # Action-distribution diagnostics
        # =============================================

        probs = (
            action_counts
            / action_counts.sum()
        )


        nz = probs[
            probs > 0
        ]


        normalized_entropy = float(

            -np.sum(
                nz
                * np.log(
                    nz
                )
            )

            / np.log(
                NUM_NODES_50
            )
        )


        dmr = float(
            np.mean(
                misses
            )
        )


        raw_rows.append({

            "method":
                "PPO",

            "task_seed":
                task_seed,

            "policy_seed":
                policy_seed,

            "avg_rt":
                float(
                    np.mean(
                        response_times
                    )
                ),

            "dmr":
                dmr,

            "deadline_met_ratio":
                1.0 - dmr,

            "avg_reward":
                float(
                    np.mean(
                        rewards
                    )
                ),

            "energy_depletion":
                float(
                    np.sum(
                        1.0
                        - env.energy
                    )
                ),

            "load_imbalance":
                float(
                    np.mean(
                        queue_imbalances
                    )
                ),

            "overload_ratio":
                float(
                    np.mean(
                        overloads
                    )
                ),

            "action_entropy":
                normalized_entropy,

            "dominant_node_share":
                float(
                    probs.max()
                ),

            "active_nodes":
                int(
                    np.sum(
                        action_counts > 0
                    )
                )
        })


# =====================================================
# Raw 150-run dataframe
# =====================================================

ppo50_raw = pd.DataFrame(
    raw_rows
)


# =====================================================
# Collapse 5 stochastic runs into ONE observation
# per task seed
#
# Statistical unit remains N = 30
# =====================================================

metric_columns = [

    "avg_rt",

    "dmr",

    "deadline_met_ratio",

    "avg_reward",

    "energy_depletion",

    "load_imbalance",

    "overload_ratio",

    "action_entropy",

    "dominant_node_share",

    "active_nodes"
]


ppo50_matched = (

    ppo50_raw

    .groupby(
        "task_seed",
        as_index=False
    )[metric_columns]

    .mean()
)


ppo50_matched.insert(
    0,
    "method",
    "PPO"
)


# =====================================================
# SUMMARY
# =====================================================

print(
    "\n"
    + "=" * 95
)

print(
    "📊 PPO 50-NODE STOCHASTIC FIXED-TOPOLOGY EVALUATION"
)

print(
    "=" * 95
)

print(
    "Raw stochastic runs:",
    len(
        ppo50_raw
    )
)

print(
    "Matched statistical observations:",
    len(
        ppo50_matched
    )
)


print(
    f"\nRT: "
    f"{ppo50_matched['avg_rt'].mean():.2f} "
    f"± "
    f"{ppo50_matched['avg_rt'].std(ddof=1):.2f} ms"
)


print(
    f"DMR: "
    f"{ppo50_matched['dmr'].mean():.4f} "
    f"± "
    f"{ppo50_matched['dmr'].std(ddof=1):.4f}"
)


print(
    f"Deadline Met: "
    f"{ppo50_matched['deadline_met_ratio'].mean()*100:.2f}% "
    f"± "
    f"{ppo50_matched['deadline_met_ratio'].std(ddof=1)*100:.2f}%"
)


print(
    f"Reward: "
    f"{ppo50_matched['avg_reward'].mean():.4f} "
    f"± "
    f"{ppo50_matched['avg_reward'].std(ddof=1):.4f}"
)


print(
    f"Energy depletion: "
    f"{ppo50_matched['energy_depletion'].mean():.6f} "
    f"± "
    f"{ppo50_matched['energy_depletion'].std(ddof=1):.6f}"
)


print(
    f"Load imbalance: "
    f"{ppo50_matched['load_imbalance'].mean():.6f} "
    f"± "
    f"{ppo50_matched['load_imbalance'].std(ddof=1):.6f}"
)


print(
    f"Overload ratio: "
    f"{ppo50_matched['overload_ratio'].mean():.4f}"
)


print(
    f"Action entropy: "
    f"{ppo50_matched['action_entropy'].mean():.4f}"
)


print(
    f"Dominant-node share: "
    f"{ppo50_matched['dominant_node_share'].mean()*100:.2f}%"
)


print(
    f"Active nodes: "
    f"{ppo50_matched['active_nodes'].mean():.2f} "
    f"± "
    f"{ppo50_matched['active_nodes'].std(ddof=1):.2f}"
)


# =====================================================
# SAVE
# =====================================================

PPO50_RAW_PATH = os.path.join(
    SAVE_DIR,
    "PPO_50nodes_fixed_topology_150rawruns.csv"
)


PPO50_MATCHED_PATH = os.path.join(
    SAVE_DIR,
    "PPO_50nodes_fixed_topology_30matched.csv"
)


ppo50_raw.to_csv(
    PPO50_RAW_PATH,
    index=False
)


ppo50_matched.to_csv(
    PPO50_MATCHED_PATH,
    index=False
)


