# VANILLA DDQN 100-NODE
# FULL TRAINING + 30-RUN EVALUATION
# SELF-CONTAINED
# ============================================================

import os
import time
import random
from collections import deque

import numpy as np
import pandas as pd

import torch
import torch.nn as nn
import torch.optim as optim

from ImprovedFogSchedulingEnv import ImprovedFogSchedulingEnv


SAVE_DIR = "/content/drive/MyDrive/ADDQN_Revision_2026"
os.makedirs(SAVE_DIR, exist_ok=True)


# ============================================================
# SEED
# ============================================================

def set_global_seed(seed=42):

    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)

    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

    print(f"✅ Global seed fixed at {seed}")


set_global_seed(42)


# ============================================================
# REPLAY BUFFER
# ============================================================

class ReplayBuffer:

    def __init__(self, capacity=100000, device=None):

        self.buffer = deque(maxlen=capacity)

        self.device = (
            device
            if device is not None
            else torch.device(
                "cuda"
                if torch.cuda.is_available()
                else "cpu"
            )
        )


    def __len__(self):
        return len(self.buffer)


    def add(self, state, action, reward, next_state):

        self.buffer.append(
            (
                np.asarray(state, dtype=np.float32),
                int(action),
                float(reward),
                np.asarray(next_state, dtype=np.float32)
            )
        )


    def sample(self, batch_size):

        batch = random.sample(
            self.buffer,
            batch_size
        )

        states, actions, rewards, next_states = zip(*batch)

        return (
            torch.tensor(
                np.stack(states),
                dtype=torch.float32,
                device=self.device
            ),

            torch.tensor(
                actions,
                dtype=torch.long,
                device=self.device
            ),

            torch.tensor(
                rewards,
                dtype=torch.float32,
                device=self.device
            ),

            torch.tensor(
                np.stack(next_states),
                dtype=torch.float32,
                device=self.device
            )
        )


# ============================================================
# NETWORK
# ============================================================

class VanillaDQN(nn.Module):

    def __init__(self, state_dim, action_dim):

        super().__init__()

        self.net = nn.Sequential(
            nn.Linear(state_dim, 256),
            nn.ReLU(),

            nn.Linear(256, 256),
            nn.ReLU(),

            nn.Linear(256, action_dim)
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)

        return self.net(x)


# ============================================================
# DOUBLE DQN AGENT
# ============================================================

class VanillaDDQNAgent:

    def __init__(
        self,
        state_dim,
        action_dim,
        lr=3e-4,
        gamma=0.99
    ):

        self.action_dim = action_dim
        self.gamma = gamma

        self.device = torch.device(
            "cuda"
            if torch.cuda.is_available()
            else "cpu"
        )


        self.policy_net = VanillaDQN(
            state_dim,
            action_dim
        ).to(self.device)


        self.target_net = VanillaDQN(
            state_dim,
            action_dim
        ).to(self.device)


        self.target_net.load_state_dict(
            self.policy_net.state_dict()
        )

        self.target_net.eval()


        self.optimizer = optim.Adam(
            self.policy_net.parameters(),
            lr=lr,
            weight_decay=1e-5
        )


        self.scheduler = optim.lr_scheduler.StepLR(
            self.optimizer,
            step_size=100,
            gamma=0.95
        )


        self.memory = ReplayBuffer(
            capacity=100000,
            device=self.device
        )

        self.loss_fn = nn.MSELoss()

        self.training_steps = 0


    def select_action(self, state, epsilon):

        if random.random() < epsilon:

            return random.randint(
                0,
                self.action_dim - 1
            )


        self.policy_net.eval()

        with torch.no_grad():

            x = torch.tensor(
                state,
                dtype=torch.float32,
                device=self.device
            )

            q = self.policy_net(x)

            return int(
                q.argmax(dim=1).item()
            )


    def train(self, batch_size=64):

        if len(self.memory) < batch_size:
            return None


        self.policy_net.train()

        state, action, reward, next_state = (
            self.memory.sample(batch_size)
        )


        current_q = (
            self.policy_net(state)
            .gather(
                1,
                action.unsqueeze(1)
            )
            .squeeze(1)
        )


        # ================================================
        # DOUBLE-DQN TARGET
        # policy selects
        # target evaluates
        # ================================================

        with torch.no_grad():

            next_actions = (
                self.policy_net(next_state)
                .argmax(
                    dim=1,
                    keepdim=True
                )
            )


            next_q = (
                self.target_net(next_state)
                .gather(
                    1,
                    next_actions
                )
                .squeeze(1)
            )


            target = (
                reward
                + self.gamma * next_q
            )


        loss = self.loss_fn(
            current_q,
            target
        )


        self.optimizer.zero_grad()

        loss.backward()


        torch.nn.utils.clip_grad_norm_(
            self.policy_net.parameters(),
            10.0
        )


        self.optimizer.step()

        self.training_steps += 1

        return float(loss.item())


    def update_target(self):

        self.target_net.load_state_dict(
            self.policy_net.state_dict()
        )


    def step_scheduler(self):

        self.scheduler.step()


    def get_current_lr(self):

        return self.optimizer.param_groups[0]["lr"]


# ============================================================
# CONFIGURATION
# ============================================================

