set_global_seed(42)


# ============================================================
# DUELING NETWORK
# ============================================================

class DuelingDQN(nn.Module):

    def __init__(self, state_dim, action_dim):

        super().__init__()

        self.feature = nn.Sequential(
            nn.Linear(state_dim, 256),
            nn.ReLU(),
            nn.Linear(256, 256),
            nn.ReLU()
        )

        self.value_stream = nn.Linear(
            256,
            1
        )

        self.advantage_stream = nn.Linear(
            256,
            action_dim
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)

        features = self.feature(x)

        value = self.value_stream(
            features
        )

        advantage = self.advantage_stream(
            features
        )

        return (
            value
            + advantage
            - advantage.mean(
                dim=1,
                keepdim=True
            )
        )


# ============================================================
# DUELING DOUBLE-DQN AGENT
# Uses ReplayBuffer already defined in previous DDQN cell
# ============================================================

class DuelingDDQNAgent:

    def __init__(
        self,
        state_dim,
        action_dim,
        lr=3e-4,
        gamma=0.99
    ):

        self.action_dim = action_dim
        self.gamma = gamma

        self.device = torch.device(
            "cuda"
            if torch.cuda.is_available()
            else "cpu"
        )


        self.policy_net = DuelingDQN(
            state_dim,
            action_dim
        ).to(self.device)


        self.target_net = DuelingDQN(
            state_dim,
            action_dim
        ).to(self.device)


        self.target_net.load_state_dict(
            self.policy_net.state_dict()
        )

        self.target_net.eval()


        self.optimizer = optim.Adam(
            self.policy_net.parameters(),
            lr=lr,
            weight_decay=1e-5
        )


        self.scheduler = optim.lr_scheduler.StepLR(
            self.optimizer,
            step_size=100,
            gamma=0.95
        )


        self.memory = ReplayBuffer(
            capacity=100000,
            device=self.device
        )


        self.loss_fn = nn.MSELoss()

        self.training_steps = 0


    def select_action(
        self,
        state,
        epsilon
    ):

        if random.random() < epsilon:

            return random.randint(
                0,
                self.action_dim - 1
            )


        self.policy_net.eval()

        with torch.no_grad():

            state_t = torch.tensor(
                state,
                dtype=torch.float32,
                device=self.device
            )

            q = self.policy_net(
                state_t
            )

            return int(
                q.argmax(dim=1).item()
            )


    def train(
        self,
        batch_size=64
    ):

        if len(self.memory) < batch_size:
            return None


        self.policy_net.train()


        state, action, reward, next_state = (
            self.memory.sample(
                batch_size
            )
        )


        current_q = (
            self.policy_net(state)
            .gather(
                1,
                action.unsqueeze(1)
            )
            .squeeze(1)
        )


        # Double-DQN target
        with torch.no_grad():

            next_actions = (
                self.policy_net(next_state)
                .argmax(
                    dim=1,
                    keepdim=True
                )
            )


            next_q = (
                self.target_net(next_state)
                .gather(
                    1,
                    next_actions
                )
                .squeeze(1)
            )


            target = (
                reward
                + self.gamma * next_q
            )


        loss = self.loss_fn(
            current_q,
            target
        )


        self.optimizer.zero_grad()

        loss.backward()


        torch.nn.utils.clip_grad_norm_(
            self.policy_net.parameters(),
            10.0
        )


        self.optimizer.step()

        self.training_steps += 1

        return float(
            loss.item()
        )


    def update_target(self):

        self.target_net.load_state_dict(
            self.policy_net.state_dict()
        )


    def step_scheduler(self):

        self.scheduler.step()


    def get_current_lr(self):

        return self.optimizer.param_groups[0]["lr"]


# ============================================================
# CONFIGURATION
# ============================================================

NUM_NODES = 100
STATE_DIM = 500
ACTION_DIM = 100

DT = 0.15

EPISODES = 500
MAX_STEPS = 200


TRAIN_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DDQN_100nodes_training_500episodes.csv"
)

MODEL_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DDQN_100nodes_final_model.pth"
)

EVAL_PATH = os.path.join(
    SAVE_DIR,
    "Dueling_DDQN_100nodes_fixed_topology_30runs.csv"
)


# ============================================================
# ENVIRONMENT + AGENT
# ============================================================

env = ImprovedFogSchedulingEnv(
    num_nodes=NUM_NODES,
    max_steps=MAX_STEPS,
    seed=42,
    dt=DT
)


dueling_100_agent = DuelingDDQNAgent(
    state_dim=STATE_DIM,
    action_dim=ACTION_DIM,
    lr=3e-4,
    gamma=0.99
)


PARAMS = sum(
    p.numel()
    for p in
    dueling_100_agent.policy_net.parameters()
)


print("=" * 110)

print(
    "🚀 DUELING DDQN 100-NODE FULL TRAINING"
)

print(
    "Device:",
    dueling_100_agent.device
)

print(
    "Parameters:",
    PARAMS
)

print(
    "Expected parameters: 220005"
)

print(
    "dt:",
    DT
)

print(
    "Interactions:",
    EPISODES * MAX_STEPS
)

print("=" * 110)


# ============================================================
# TRAINING
# ============================================================

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

rows = []

start_time = time.time()


for episode in range(EPISODES):

    state = env.reset()

    total_reward = 0.0

    rts = []
    misses = []
    overloads = []
    imbalances = []
    losses = []


    for step in range(MAX_STEPS):

        action = (
            dueling_100_agent.select_action(
                state,
                epsilon
            )
        )


        next_state, reward, done, info = (
            env.step(action)
        )


        dueling_100_agent.memory.add(
            state,
            action,
            reward,
            next_state
        )


        loss = dueling_100_agent.train(
            batch_size=64
        )


        if loss is not None:
            losses.append(loss)


        total_reward += reward

        rts.append(
            info["response_time"]
        )

        misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        imbalances.append(
            np.std(env.queue_ms)
            / env.queue_cap_ms
        )


        state = next_state


        if done:
            break


    if episode % 5 == 0:
        dueling_100_agent.update_target()


    dueling_100_agent.step_scheduler()


    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )


    dmr = float(
        np.mean(misses)
    )


    rows.append({

        "episode":
            episode + 1,

        "total_reward":
            float(total_reward),

        "avg_rt":
            float(np.mean(rts)),

        "dmr":
            dmr,

        "deadline_met_ratio":
            1.0 - dmr,

        "overload_ratio":
            float(np.mean(overloads)),

        "load_imbalance":
            float(np.mean(imbalances)),

        "avg_loss":
            (
                float(np.mean(losses))
                if losses
                else np.nan
            ),

        "epsilon":
            epsilon,

        "learning_rate":
            dueling_100_agent.get_current_lr(),

        "training_steps":
            dueling_100_agent.training_steps
    })


    if (
        episode == 0
        or (episode + 1) % 10 == 0
    ):

        recent = pd.DataFrame(
            rows
        ).tail(10)

        print(
            f"Ep {episode+1:3d}/500 | "
            f"R={recent['total_reward'].mean():8.1f} | "
            f"RT={recent['avg_rt'].mean():7.2f} | "
            f"DMR={recent['dmr'].mean():.3f} | "
            f"Over={recent['overload_ratio'].mean():.3f} | "
            f"Loss={recent['avg_loss'].mean():9.2f} | "
            f"Eps={epsilon:.4f}"
        )


    if (episode + 1) % 10 == 0:

        pd.DataFrame(
            rows
        ).to_csv(
            TRAIN_PATH,
            index=False
        )


# ============================================================
