# ============================================================
# MODEL DEFINITIONS
# ============================================================

# ------------------------------------------------------------
# Vanilla DQN / DDQN
# ------------------------------------------------------------

class VanillaDQNNet(nn.Module):

    def __init__(
        self,
        state_dim,
        action_dim
    ):

        super().__init__()

        self.net = nn.Sequential(

            nn.Linear(
                state_dim,
                256
            ),

            nn.ReLU(),

            nn.Linear(
                256,
                256
            ),

            nn.ReLU(),

            nn.Linear(
                256,
                action_dim
            )
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)

        return self.net(x)


# ------------------------------------------------------------
# Dueling DDQN
# ------------------------------------------------------------

class DuelingDQNNet(nn.Module):

    def __init__(
        self,
        state_dim,
        action_dim
    ):

        super().__init__()

        self.feature = nn.Sequential(

            nn.Linear(
                state_dim,
                256
            ),

            nn.ReLU(),

            nn.Linear(
                256,
                256
            ),

            nn.ReLU()
        )


        self.value_stream = nn.Linear(
            256,
            1
        )


        self.advantage_stream = nn.Linear(
            256,
            action_dim
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)


        z = self.feature(x)

        value = self.value_stream(z)

        advantage = (
            self.advantage_stream(z)
        )


        return (
            value
            + advantage
            - advantage.mean(
                dim=1,
                keepdim=True
            )
        )


# ------------------------------------------------------------
# PPO
# ------------------------------------------------------------

class PPONet(nn.Module):

    def __init__(
        self,
        state_dim,
        action_dim
    ):

        super().__init__()

        self.shared = nn.Sequential(

            nn.Linear(
                state_dim,
                256
            ),

            nn.ReLU(),

            nn.Linear(
                256,
                256
            ),

            nn.ReLU()
        )


        self.actor = nn.Linear(
            256,
            action_dim
        )


        self.critic = nn.Linear(
            256,
            1
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)


        z = self.shared(x)

        logits = self.actor(z)

        value = self.critic(z)

        return logits, value


# ------------------------------------------------------------
# ADDQN
#
# Exact parameter counts:
# N=15  -> 85,200
# N=50  -> 161,395
# N=100 -> 270,245
# ------------------------------------------------------------

class ADDQNNet(nn.Module):

    def __init__(
        self,
        num_nodes
    ):

        super().__init__()

        self.num_nodes = num_nodes

        self.features_per_node = 5


        self.node_encoder = nn.Sequential(

            nn.Linear(
                5,
                32
            ),

            nn.BatchNorm1d(
                32
            ),

            nn.ReLU(),

            nn.Linear(
                32,
                16
            ),

            nn.BatchNorm1d(
                16
            ),

            nn.ReLU()
        )


        self.attention = nn.Linear(
            16,
            1
        )


        self.context_path = nn.Sequential(

            nn.Linear(
                16,
                128
            ),

            nn.ReLU(),

            nn.Linear(
                128,
                128
            ),

            nn.ReLU(),

            nn.Dropout(
                0.2
            )
        )


        self.flat_path = nn.Sequential(

            nn.Linear(
                16 * num_nodes,
                128
            ),

            nn.ReLU(),

            nn.Dropout(
                0.1
            )
        )


        self.fusion = nn.Sequential(

            nn.Linear(
                256,
                128
            ),

            nn.ReLU()
        )


        self.output = nn.Linear(
            128,
            num_nodes
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)


        batch_size = x.shape[0]


        nodes = x.view(
            batch_size,
            self.num_nodes,
            5
        )


        # BN operates over all encoded nodes
        flat_nodes = nodes.reshape(
            batch_size * self.num_nodes,
            5
        )


        encoded = self.node_encoder(
            flat_nodes
        )


        encoded = encoded.view(
            batch_size,
            self.num_nodes,
            16
        )


        attention_scores = (
            self.attention(
                encoded
            )
            .squeeze(-1)
        )


        attention_weights = (
            torch.softmax(
                attention_scores,
                dim=1
            )
        )


        context = torch.sum(

            encoded
            * attention_weights.unsqueeze(-1),

            dim=1
        )


        context_features = (
            self.context_path(
                context
            )
        )


        flat_features = (
            self.flat_path(
                encoded.reshape(
                    batch_size,
                    -1
                )
            )
        )


        combined = torch.cat(
            [
                context_features,
                flat_features
            ],
            dim=1
        )


        fused = self.fusion(
            combined
        )


        return self.output(
            fused
        )


