# ============================================================
# WORKLOAD SCENARIOS
# ============================================================

def get_dt(scenario, step):

    # --------------------------------------------------------
    # 1. Stationary baseline
    # --------------------------------------------------------
    if scenario == "Stationary":

        return 0.30


    # --------------------------------------------------------
    # 2. Periodic 2x bursts
    #
    # Normal: dt = 0.30
    # Burst : dt = 0.15
    #
    # Bursts:
    # steps 50-79
    # steps 130-159
    # --------------------------------------------------------
    elif scenario == "Bursty_2x":

        if (
            50 <= step < 80
            or
            130 <= step < 160
        ):
            return 0.15

        return 0.30


    # --------------------------------------------------------
    # 3. Nonstationary changing load
    #
    # 0-49    : dt 0.30
    # 50-99   : dt 0.20
    # 100-149 : dt 0.15
    # 150-199 : dt 0.30
    # --------------------------------------------------------
    elif scenario == "Nonstationary":

        if step < 50:
            return 0.30

        elif step < 100:
            return 0.20

        elif step < 150:
            return 0.15

        else:
            return 0.30


    else:
        raise ValueError(
            f"Unknown scenario: {scenario}"
        )


SCENARIOS = [
    "Stationary",
    "Bursty_2x",
    "Nonstationary"
]


# ============================================================
# SAVE PROTOCOL DESCRIPTION
# ============================================================

protocol_text = """
Dynamic/Bursty Workload Evaluation
===================================

Network size:
50 fog nodes

Episode length:
200 task arrivals

Topology:
Fixed training topology seed = 42

Evaluation task seeds:
100-129 (30 matched task streams)

Base dt:
0.30

Scenarios
---------

1. Stationary
   dt = 0.30 for all 200 steps.

2. Bursty_2x
   dt = 0.30 normally.
   dt = 0.15 during steps 50-79 and 130-159.
   These intervals represent approximately doubled workload
   intensity relative to the baseline service interval.

3. Nonstationary
   steps   0-49  : dt = 0.30
   steps  50-99  : dt = 0.20
   steps 100-149 : dt = 0.15
   steps 150-199 : dt = 0.30

Policies are evaluated without retraining.

Deterministic value-based methods:
1 run per task seed.

PPO:
5 stochastic policy seeds per task stream,
then averaged to produce 30 matched statistical observations.

Metrics:
Response time
Deadline miss ratio
Deadline met ratio
Mean reward
Energy depletion
Load imbalance
Overload ratio
Action entropy
Dominant-node share
Active nodes
"""

with open(
    PROTOCOL_PATH,
    "w"
) as f:

    f.write(protocol_text)


# ============================================================
# MODEL DEFINITIONS
# ============================================================

class VanillaNet(nn.Module):

    def __init__(
        self,
        state_dim,
        action_dim
    ):

        super().__init__()

        self.net = nn.Sequential(

            nn.Linear(
                state_dim,
                256
            ),

            nn.ReLU(),

            nn.Linear(
                256,
                256
            ),

            nn.ReLU(),

            nn.Linear(
                256,
                action_dim
            )
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)

        return self.net(x)


# ------------------------------------------------------------

class DuelingNet(nn.Module):

    def __init__(
        self,
        state_dim,
        action_dim
    ):

        super().__init__()

        self.feature = nn.Sequential(

            nn.Linear(
                state_dim,
                256
            ),

            nn.ReLU(),

            nn.Linear(
                256,
                256
            ),

            nn.ReLU()
        )

        self.value_stream = nn.Linear(
            256,
            1
        )

        self.advantage_stream = nn.Linear(
            256,
            action_dim
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)

        z = self.feature(x)

        value = self.value_stream(z)

        advantage = (
            self.advantage_stream(z)
        )

        return (
            value
            + advantage
            - advantage.mean(
                dim=1,
                keepdim=True
            )
        )


# ------------------------------------------------------------

class PPONet(nn.Module):

    def __init__(
        self,
        state_dim,
        action_dim
    ):

        super().__init__()

        self.shared = nn.Sequential(

            nn.Linear(
                state_dim,
                256
            ),

            nn.ReLU(),

            nn.Linear(
                256,
                256
            ),

            nn.ReLU()
        )

        self.actor = nn.Linear(
            256,
            action_dim
        )

        self.critic = nn.Linear(
            256,
            1
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)

        z = self.shared(x)

        return (
            self.actor(z),
            self.critic(z)
        )


# ------------------------------------------------------------

class ADDQNNet(nn.Module):

    def __init__(
        self,
        num_nodes
    ):

        super().__init__()

        self.num_nodes = num_nodes


        self.node_encoder = nn.Sequential(

            nn.Linear(
                5,
                32
            ),

            nn.BatchNorm1d(
                32
            ),

            nn.ReLU(),

            nn.Linear(
                32,
                16
            ),

            nn.BatchNorm1d(
                16
            ),

            nn.ReLU()
        )


        self.attention = nn.Linear(
            16,
            1
        )


        self.context_path = nn.Sequential(

            nn.Linear(
                16,
                128
            ),

            nn.ReLU(),

            nn.Linear(
                128,
                128
            ),

            nn.ReLU(),

            nn.Dropout(
                0.2
            )
        )


        self.flat_path = nn.Sequential(

            nn.Linear(
                16 * num_nodes,
                128
            ),

            nn.ReLU(),

            nn.Dropout(
                0.1
            )
        )


        self.fusion = nn.Sequential(

            nn.Linear(
                256,
                128
            ),

            nn.ReLU()
        )


        self.output = nn.Linear(
            128,
            num_nodes
        )


    def forward(self, x):

        if x.dim() == 1:
            x = x.unsqueeze(0)

        batch = x.shape[0]


        nodes = x.view(
            batch,
            self.num_nodes,
            5
        )


        encoded = self.node_encoder(

            nodes.reshape(
                batch * self.num_nodes,
                5
            )
        )


        encoded = encoded.view(
            batch,
            self.num_nodes,
            16
        )


        scores = (
            self.attention(
                encoded
            )
            .squeeze(-1)
        )


        weights = torch.softmax(
            scores,
            dim=1
        )


        context = torch.sum(

            encoded
            * weights.unsqueeze(-1),

            dim=1
        )


        context_features = (
            self.context_path(
                context
            )
        )


        flat_features = (
            self.flat_path(

                encoded.reshape(
                    batch,
                    -1
                )
            )
        )


        fused = self.fusion(

            torch.cat(
                [
                    context_features,
                    flat_features
                ],
                dim=1
            )
        )


        return self.output(
            fused
        )


