assert PARAMS == 161395


# ============================================================
# TRAINING
# ============================================================

epsilon = 1.0
epsilon_min = 0.05
epsilon_decay = 0.995

rows = []

start_time = time.time()


for episode in range(
    EPISODES
):

    state = env.reset()

    total_reward = 0.0

    rts = []
    misses = []
    overloads = []
    imbalances = []
    losses = []


    for step in range(
        MAX_STEPS
    ):

        action = agent.select_action(
            state,
            epsilon
        )


        next_state, reward, done, info = (
            env.step(
                action
            )
        )


        agent.memory.add(
            state,
            action,
            reward,
            next_state
        )


        loss = agent.train(
            batch_size=64
        )


        if loss is not None:
            losses.append(loss)


        total_reward += reward

        rts.append(
            info["response_time"]
        )

        misses.append(
            info["deadline_miss"]
        )

        overloads.append(
            info["overload"]
        )

        imbalances.append(
            np.std(env.queue_ms)
            / env.queue_cap_ms
        )


        state = next_state


        if done:
            break


    # Same original target update schedule
    if episode % 5 == 0:
        agent.update_target()


    agent.step_scheduler()


    epsilon = max(
        epsilon_min,
        epsilon * epsilon_decay
    )


    dmr = float(
        np.mean(misses)
    )


    rows.append({

        "episode":
            episode + 1,

        "deadline_weight":
            DEADLINE_WEIGHT,

        "total_reward":
            total_reward,

        "avg_rt":
            np.mean(rts),

        "dmr":
            dmr,

        "deadline_met_ratio":
            1.0 - dmr,

        "overload_ratio":
            np.mean(overloads),

        "load_imbalance":
            np.mean(imbalances),

        "avg_loss":
            (
                np.mean(losses)
                if losses
                else np.nan
            ),

        "epsilon":
            epsilon,

        "learning_rate":
            agent.get_current_lr()
    })


    # Save frequently
    if (episode + 1) % 10 == 0:

        pd.DataFrame(
            rows
        ).to_csv(
            TRAIN_PATH,
            index=False
        )


        recent = pd.DataFrame(
            rows
        ).tail(10)


