# ============================================================
# STATISTICAL HELPERS
# ============================================================

def rank_biserial_paired(
    x,
    y
):

    diff = np.asarray(x) - np.asarray(y)

    diff = diff[
        diff != 0
    ]


    if len(diff) == 0:
        return 0.0


    ranks = rankdata(
        np.abs(diff)
    )


    return float(

        np.sum(
            np.sign(diff)
            * ranks
        )

        / np.sum(ranks)
    )


def paired_test(
    df_a,
    df_b,
    value_col,
    method_a,
    method_b,
    context,
    family,
    lower_is_better=True
):

    a = df_a[
        [
            "task_seed",
            value_col
        ]
    ].copy()


    b = df_b[
        [
            "task_seed",
            value_col
        ]
    ].copy()


    merged = a.merge(

        b,

        on="task_seed",

        suffixes=(
            "_A",
            "_B"
        )
    )


    x = merged[
        f"{value_col}_A"
    ].to_numpy()


    y = merged[
        f"{value_col}_B"
    ].to_numpy()


    diff = x - y


    if np.allclose(
        diff,
        0
    ):

        statistic = 0.0
        p_value = 1.0

    else:

        test = wilcoxon(

            x,
            y,

            alternative="two-sided",

            zero_method="wilcox",

            method="auto"
        )

        statistic = float(
            test.statistic
        )

        p_value = float(
            test.pvalue
        )


    rb = rank_biserial_paired(
        x,
        y
    )


    mean_a = float(
        np.mean(x)
    )

    mean_b = float(
        np.mean(y)
    )


    if lower_is_better:

        if mean_a < mean_b:
            better = method_a

        elif mean_b < mean_a:
            better = method_b

        else:
            better = "Tie"

    else:

        if mean_a > mean_b:
            better = method_a

        elif mean_b > mean_a:
            better = method_b

        else:
            better = "Tie"


    return {

        "family":
            family,

        "context":
            context,

        "comparison":
            f"{method_a} vs {method_b}",

        "method_A":
            method_a,

        "method_B":
            method_b,

        "metric":
            value_col,

        "n_pairs":
            len(merged),

        "mean_A":
            mean_a,

        "mean_B":
            mean_b,

        "mean_difference_A_minus_B":
            float(
                np.mean(diff)
            ),

        "median_difference_A_minus_B":
            float(
                np.median(diff)
            ),

        "wilcoxon_W":
            statistic,

        "p_raw":
            p_value,

        "rank_biserial":
            rb,

        "better_method":
            better
    }


# ============================================================
# HOLM-BONFERRONI
# ============================================================

def holm_adjust(
    p_values
):

    p_values = np.asarray(
        p_values,
        dtype=float
    )


    m = len(
        p_values
    )


    order = np.argsort(
        p_values
    )


    sorted_p = p_values[
        order
    ]


    adjusted_sorted = np.zeros(
        m
    )


    running_max = 0.0


    for i, p in enumerate(
        sorted_p
    ):

        adjusted = (
            (m - i)
            * p
        )


        adjusted = min(
            adjusted,
            1.0
        )


        running_max = max(
            running_max,
            adjusted
        )


        adjusted_sorted[i] = (
            running_max
        )


    result = np.empty(
        m
    )


    result[
        order
    ] = adjusted_sorted


    return result


