# ============================================================
# SIGNIFICANCE LABELS
# ============================================================

def significance(
    p
):

    if p < 0.001:
        return "***"

    elif p < 0.01:
        return "**"

    elif p < 0.05:
        return "*"

    else:
        return "ns"


stats_df[
    "significance"
] = stats_df[
    "p_holm"
].apply(
    significance
)


stats_df[
    "significant_0.05"
] = (
    stats_df[
        "p_holm"
    ] < 0.05
)


